			end
		end)
		window.OnActivate:Connect(function()
			Explorer.Active = true
			Explorer.UpdateView()
			Explorer.Update()
			Explorer.Refresh()
		end)
		window.OnRestore:Connect(function()
			Explorer.Active = true
			Explorer.UpdateView()
			Explorer.Update()
			Explorer.Refresh()
		end)
		window.OnDeactivate:Connect(function() Explorer.Active = false end)
		window.OnMinimize:Connect(function() Explorer.Active = false end)

		
		autoUpdateSearch = Settings.Explorer.AutoUpdateSearch

		
		table.clear(nodes) 
		nodes[game] = {Obj = game}
		nodes[rawGame] = nodes[game]
		expanded[nodes[game]] = true

		
		if env.getnilinstances then
			nodes[nilNode.Obj] = nilNode
		end

		Explorer.SetupConnections()
		Main.AddCommands(Explorer.GetActions)

		local insts = getDescendants(game)
		for i = 1,#insts do
			local obj = insts[i]
			local ok,parObj = pcall(ffa,obj,"Instance") 
			local par = ok and nodes[parObj]
			if not par then continue end
			local newNode = {Obj = obj, Parent = par}
			nodes[obj] = newNode
			par[#par+1] = newNode
		end
	end

	return Explorer
end

return {InitDeps = initDeps, InitAfterMain = initAfterMain, Main = main}

end,
["Flowchart"] = function()


local Main,Lib,Apps,Settings 
local service,createSimple 
local Analysis

local function initDeps(data)
	Main = data.Main
	Lib = data.Lib
	Apps = data.Apps
	Settings = data.Settings

	service = data.service
	createSimple = data.createSimple
end

local function initAfterMain()
	Analysis = Apps.ScriptAnalysis
end

local function main()
	local Flowchart = {}

	local FONT, TEXT_SIZE, LINE_H = Enum.Font.Code, 13, 15
	local BADGE_H = 18
	local MIN_ZOOM, MAX_ZOOM = 0.15, 2.5
	local HEADER_H = 44

	local FILL = {
		start = Color3.fromRGB(38,92,60), root = Color3.fromRGB(38,92,60),
		block = Color3.fromRGB(62,62,62), func = Color3.fromRGB(58,74,92),
		cond = Color3.fromRGB(56,70,106), loop = Color3.fromRGB(86,62,106),
		ret = Color3.fromRGB(106,52,52), ["break"] = Color3.fromRGB(74,74,74), continue = Color3.fromRGB(74,74,74),
		remote = Color3.fromRGB(122,80,36), http = Color3.fromRGB(122,80,36), dynamic = Color3.fromRGB(112,42,92),
	}
	
	local TINT = {remote = FILL.remote, http = FILL.http, dynamic = FILL.dynamic, calls = Color3.fromRGB(46,76,104), unused = Color3.fromRGB(44,44,44)}
	local PILL = {cond = true, loop = true, start = true, root = true, ["break"] = true, continue = true}
	local CENTERED = {cond = true, loop = true, start = true, root = true, ret = true, ["break"] = true, continue = true, func = true, remote = true, http = true, dynamic = true}
	local EDGE = {
		next = Color3.fromRGB(110,150,230), ["true"] = Color3.fromRGB(80,200,100), ["false"] = Color3.fromRGB(230,90,90),
		back = Color3.fromRGB(240,170,60), ["break"] = Color3.fromRGB(160,160,160),
		call = Color3.fromRGB(110,150,230), def = Color3.fromRGB(150,150,150),
		remote = Color3.fromRGB(240,150,60), http = Color3.fromRGB(240,150,60), dynamic = Color3.fromRGB(220,90,190),
	}
	local STROKE, SELECTED, MATCH = Color3.fromRGB(150,150,150), Color3.fromRGB(255,220,90), Color3.fromRGB(80,200,255)
	local OPEN_COLOR, CALLS_COLOR = Color3.fromRGB(120,200,255), Color3.fromRGB(150,230,170)

	local LEGEND_NODES = {
		{FILL.start,"Start of the function"},
		{FILL.block,"Plain statements"},
		{TINT.calls,"Statements that call the script's own functions"},
		{FILL.cond,"Condition (if / elseif)"},
		{FILL.loop,"Loop"},
		{FILL.ret,"Return"},
		{FILL["break"],"break / continue"},
		{FILL.func,"A function (call graph)"},
		{FILL.remote,"Remote, HTTP or loadstring call"},
	}
	local LEGEND_EDGES = {
		{EDGE.next,"Next statement"},
		{EDGE["true"],"Condition is true"},
		{EDGE["false"],"Condition is false"},
		{EDGE.back,"Back to the top of a loop"},
		{EDGE["break"],"Leaves a loop"},
		{EDGE.call,"Calls (call graph)"},
		{EDGE.def,"Defined here, as a callback (call graph)"},
		{EDGE.remote,"Remote or HTTP call (call graph)"},
	}
	local LEGEND_BUTTONS = {
		{OPEN_COLOR,"open ...  opens a function defined in the box"},
		{CALLS_COLOR,"calls ...  opens a function the box calls"},
	}

	
	local MODES = {
		{"flow","Function",58,"The flowchart of one function: the one the cursor is in, or one picked on the left"},
		{"calls","Calls",42,"The call graph of the script: which function calls which"},
		{"modules","Modules",58,"The modules around the script: what it requires and what requires it"},
	}

	local pane, viewport, panFrame, canvas, uiScale
	local edgeLayer, nodeLayer, labelLayer
	local titleButton, infoLabel, emptyLabel
	local modeButtons, onMode = {}, nil
	local searchBox, searchCount, legend
	local active = function() return true end
	local graph, opts = nil, {}
	local nodeFrames, selectedId = {}, nil
	local matchSet, matchList, matchIdx = {}, {}, 0
	local zoom, panX, panY = 1, 0, 0
	local pendingFit = false
	local panning, panStart, panOrigin, panMoved = false, nil, nil, 0
	local lastClick = {}
	local functionMenu, badgeMenu
	local views = setmetatable({},{__mode = "k"}) 
	local viewKey

	local textService = service.TextService

	
	local function measure(nd)
		local widest, lines = 0, 0
		for line in ((nd.label or "").."\n"):gmatch("(.-)\n") do
			lines = lines + 1
			local ok, size = pcall(function()
				return textService:GetTextSize(line,TEXT_SIZE,FONT,Vector2.new(10000,100))
			end)
			widest = math.max(widest,ok and size.X or #line*7)
		end
		local rows = ((nd.funcs and #nd.funcs > 0) and 1 or 0) + ((nd.calls and #nd.calls > 0) and 1 or 0)
		local w = math.clamp(widest+20,70,420)
		if rows > 0 then w = math.max(w,150) end
		return w, math.max(1,lines)*LINE_H + 12 + rows*BADGE_H
	end

	local function applyView()
		panFrame.Position = UDim2.fromOffset(panX,panY)
		uiScale.Scale = zoom
		if viewKey then views[viewKey] = {zoom = zoom, panX = panX, panY = panY} end
	end

	local function fit()
		if not graph or not graph.w then return end
		local vw,vh = viewport.AbsoluteSize.X,viewport.AbsoluteSize.Y
		if vw < 10 or vh < 10 then
			pendingFit = true 
			return
		end
		pendingFit = false
		zoom = math.clamp(math.min((vw-24)/graph.w,(vh-24)/graph.h,1),0.35,1)
		panX = math.max(12,(vw-graph.w*zoom)/2)
		panY = 12
		applyView()
	end

	
	local function zoomAt(factor,cx,cy)
		local newZoom = math.clamp(zoom*factor,MIN_ZOOM,MAX_ZOOM)
		if newZoom == zoom then return end
		cx = cx or viewport.AbsoluteSize.X/2
		cy = cy or viewport.AbsoluteSize.Y/2
		local px,py = (cx-panX)/zoom,(cy-panY)/zoom
		zoom = newZoom
		panX,panY = cx-px*zoom,cy-py*zoom
		applyView()
	end

	
	local function reveal(nd,centre)
		local vw,vh = viewport.AbsoluteSize.X,viewport.AbsoluteSize.Y
		local left,top = panX+nd.x*zoom,panY+nd.y*zoom
		if centre or left < 0 or top < 0 or left+nd.w*zoom > vw or top+nd.h*zoom > vh then
			panX = vw/2 - (nd.x+nd.w/2)*zoom
			panY = vh/2 - (nd.y+nd.h/2)*zoom
			applyView()
		end
	end

	
	local function applyStroke(id)
		local f = nodeFrames[id]
		if not f then return end
		if id == selectedId then
			f.Stroke.Color,f.Stroke.Thickness = SELECTED,2
		elseif matchSet[id] then
			f.Stroke.Color,f.Stroke.Thickness = MATCH,2
		else
			f.Stroke.Color,f.Stroke.Thickness = STROKE,1
		end
	end

	local function setSelected(id)
		local old = selectedId
		selectedId = id
		applyStroke(old)
		applyStroke(id)
	end

	
	local function bar(x1,y1,x2,y2,color)
		local f = Instance.new("Frame")
		f.BackgroundColor3 = color
		f.BorderSizePixel = 0
		if y1 == y2 then
			f.Position = UDim2.fromOffset(math.min(x1,x2)-1,y1-1)
			f.Size = UDim2.fromOffset(math.abs(x2-x1)+2,2)
		else
			f.Position = UDim2.fromOffset(x1-1,math.min(y1,y2)-1)
			f.Size = UDim2.fromOffset(2,math.abs(y2-y1)+2)
		end
		f.Parent = edgeLayer
	end

	
	local function arrow(x,y,color)
		for _,side in ipairs({-1,1}) do
			local f = Instance.new("Frame")
			f.AnchorPoint = Vector2.new(0.5,0.5)
			f.BackgroundColor3 = color
			f.BorderSizePixel = 0
			f.Size = UDim2.fromOffset(9,2)
			f.Position = UDim2.fromOffset(x+side*2.83,y-2.83)
			f.Rotation = -side*45
			f.Parent = edgeLayer
		end
	end

	
	local function showBadgeMenu(list)
		badgeMenu = badgeMenu or Lib.ContextMenu.new()
		badgeMenu.Iconless = true
		badgeMenu.Width = 260
		badgeMenu:Clear()
		for _,f in ipairs(list) do
			badgeMenu:Add({Name = Analysis.Signature(graph.R,f), OnClick = function()
				if opts.OnOpenFunction then opts.OnOpenFunction(f) end
			end})
		end
		badgeMenu:Show()
	end

	local function onNodeClick(nd)
		if panMoved > 4 then return end 

		setSelected(nd.id)
		local now = tick()
		local double = lastClick.id == nd.id and now - lastClick.time < 0.4
		lastClick = {id = nd.id, time = now}

		if opts.OnSelect then opts.OnSelect(nd) end
		if double and nd.fn and opts.OnOpenFunction then opts.OnOpenFunction(nd.fn) end
	end

	
	local function badgeButton(parent,y,text,color,list)
		local btn = createSimple("TextButton",{
			AutoButtonColor = false,
			BackgroundColor3 = Color3.fromRGB(28,28,28),
			BackgroundTransparency = 0.3,
			BorderSizePixel = 0,
			Position = UDim2.new(0,4,1,y),
			Size = UDim2.new(1,-8,0,BADGE_H - 4),
			Font = Enum.Font.SourceSans,
			TextSize = 13,
			TextColor3 = color,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Text = text,
			Parent = parent,
		})
		btn.MouseButton1Click:Connect(function()
			if panMoved > 4 then return end
			if #list == 1 then
				if opts.OnOpenFunction then opts.OnOpenFunction(list[1]) end
			else
				showBadgeMenu(list)
			end
		end)
		return btn
	end

	local function makeNode(nd)
		local base = TINT[nd.tint] or FILL[nd.kind] or FILL.block
		local funcs,calls = nd.funcs or {},nd.calls or {}
		local rows = (#funcs > 0 and 1 or 0) + (#calls > 0 and 1 or 0)

		local b = createSimple("TextButton",{
			Name = "N"..nd.id,
			AutoButtonColor = false,
			BackgroundColor3 = base,
			BorderSizePixel = 0,
			ClipsDescendants = true,
			Position = UDim2.fromOffset(nd.x,nd.y),
			Size = UDim2.fromOffset(nd.w,nd.h),
			Font = FONT,
			TextSize = TEXT_SIZE,
			TextColor3 = Color3.fromRGB(232,232,232),
			Text = nd.label or "",
			TextXAlignment = CENTERED[nd.kind] and Enum.TextXAlignment.Center or Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Center,
		})
		createSimple("UICorner",{CornerRadius = PILL[nd.kind] and UDim.new(0.5,0) or UDim.new(0,4), Parent = b})
		local stroke = createSimple("UIStroke",{ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Color = STROKE, Thickness = 1, Parent = b})
		createSimple("UIPadding",{PaddingLeft = UDim.new(0,8), PaddingRight = UDim.new(0,8), PaddingBottom = UDim.new(0,rows*BADGE_H), Parent = b})

		
		local y = -(BADGE_H - 1)
		if #funcs > 0 then
			local text = #funcs == 1 and ("open "..Analysis.Signature(graph.R,funcs[1])) or ("open "..#funcs.." functions")
			badgeButton(b,y,text,OPEN_COLOR,funcs)
			y = y - BADGE_H
		end
		if #calls > 0 then
			local text = #calls == 1 and ("calls "..Analysis.Signature(graph.R,calls[1])) or ("calls "..#calls.." functions")
			badgeButton(b,y,text,CALLS_COLOR,calls)
		end

		b.MouseEnter:Connect(function() b.BackgroundColor3 = base:Lerp(Color3.new(1,1,1),0.12) end)
		b.MouseLeave:Connect(function() b.BackgroundColor3 = base end)
		b.MouseButton1Click:Connect(function() onNodeClick(nd) end)

		b.Parent = nodeLayer
		nodeFrames[nd.id] = {Frame = b, Stroke = stroke}
	end

	
	local function searchText(nd)
		local parts = {nd.label or ""}
		for _,f in ipairs(nd.funcs or {}) do parts[#parts+1] = Analysis.Signature(graph.R,f) end
		for _,f in ipairs(nd.calls or {}) do parts[#parts+1] = Analysis.Signature(graph.R,f) end
		return table.concat(parts," "):lower()
	end

	local function centreOn(nd)
		reveal(nd,true)
	end

	
	local function runSearch(bringIntoView)
		matchSet,matchList,matchIdx = {},{},0
		local needle = searchBox.Text:lower()
		if needle ~= "" and graph then
			for _,nd in ipairs(graph.nodes) do
				if nd.search and nd.search:find(needle,1,true) then
					matchSet[nd.id] = true
					matchList[#matchList+1] = nd
				end
			end
		end
		for id in pairs(nodeFrames) do applyStroke(id) end

		searchCount.Text = needle == "" and "" or (#matchList == 0 and "none" or (#matchList.." found"))
		if bringIntoView and #matchList > 0 then
			matchIdx = 1
			centreOn(matchList[1])
		end
	end

	local function nextMatch(step)
		if #matchList == 0 then return end
		matchIdx = (matchIdx - 1 + step) % #matchList + 1
		centreOn(matchList[matchIdx])
		searchCount.Text = ("%d of %d"):format(matchIdx,#matchList)
	end

	local function render()
		for _,layer in ipairs({edgeLayer,nodeLayer,labelLayer}) do
			layer:ClearAllChildren()
		end
		nodeFrames = {}
		selectedId = nil
		canvas.Size = UDim2.fromOffset(graph.w,graph.h)

		for _,e in ipairs(graph.edges) do
			if e.pts and #e.pts >= 2 then
				local color = EDGE[e.kind] or EDGE.next
				for i = 1,#e.pts-1 do
					local p,q = e.pts[i],e.pts[i+1]
					bar(p[1],p[2],q[1],q[2],color)
				end
				local last = e.pts[#e.pts]
				arrow(last[1],last[2],color)

				if e.label and e.label ~= "" and e.lx then
					createSimple("TextLabel",{
						BackgroundTransparency = 1,
						Position = UDim2.fromOffset(e.lx,e.ly),
						Size = UDim2.fromOffset(60,12),
						Font = FONT,
						TextSize = 11,
						TextColor3 = color,
						TextXAlignment = Enum.TextXAlignment.Left,
						Text = e.label,
						Parent = labelLayer,
					})
				end
			end
		end
		for _,nd in ipairs(graph.nodes) do
			nd.search = searchText(nd)
			makeNode(nd)
		end
		runSearch(false)
	end

	local function showFunctionMenu()
		local list = opts.Functions
		if type(list) == "function" then list = list() end 
		if not list or #list == 0 then return end

		functionMenu = functionMenu or Lib.ContextMenu.new()
		functionMenu.Iconless = true
		functionMenu.SearchEnabled = true
		functionMenu.Width = 280
		functionMenu.MaxHeight = 320
		functionMenu:Clear()
		for _,entry in ipairs(list) do
			functionMenu:Add({Name = entry.label, OnClick = function()
				if opts.OnPickFunction then opts.OnPickFunction(entry) end
			end})
		end
		functionMenu:Show()
	end

	
	local function buildLegend()
		legend = createSimple("Frame",{
			Name = "Legend",
			AnchorPoint = Vector2.new(1,0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundColor3 = Settings.Theme.Menu,
			BackgroundTransparency = 0.05,
			BorderSizePixel = 0,
			Position = UDim2.new(1,-8,0,8),
			Size = UDim2.new(0,300,0,0),
			Visible = false,
			ZIndex = 6,
			Parent = viewport,
		})
		createSimple("UICorner",{CornerRadius = UDim.new(0,4),Parent = legend})
		createSimple("UIStroke",{Color = Settings.Theme.Outline2,Thickness = 1,Parent = legend})
		createSimple("UIPadding",{PaddingLeft = UDim.new(0,8),PaddingRight = UDim.new(0,8),PaddingTop = UDim.new(0,6),PaddingBottom = UDim.new(0,6),Parent = legend})
		createSimple("UIListLayout",{SortOrder = Enum.SortOrder.LayoutOrder,Padding = UDim.new(0,2),Parent = legend})

		local order = 0
		local function line(color,text,isEdge,heading)
			order = order + 1
			local row = createSimple("Frame",{BackgroundTransparency = 1,Size = UDim2.new(1,0,0,heading and 18 or 16),LayoutOrder = order,ZIndex = 6,Parent = legend})
			if heading then
				createSimple("TextLabel",{BackgroundTransparency = 1,Size = UDim2.new(1,0,1,0),Font = Enum.Font.SourceSansBold,TextSize = 13,TextColor3 = Settings.Theme.Text,TextXAlignment = Enum.TextXAlignment.Left,Text = text,ZIndex = 6,Parent = row})
				return
			end
			createSimple("Frame",{
				BackgroundColor3 = color,
				BorderSizePixel = 0,
				Position = UDim2.new(0,0,0,isEdge and 7 or 3),
				Size = UDim2.new(0,22,0,isEdge and 2 or 10),
				ZIndex = 6,
				Parent = row,
			})
			createSimple("TextLabel",{BackgroundTransparency = 1,Position = UDim2.new(0,30,0,0),Size = UDim2.new(1,-30,1,0),Font = Enum.Font.SourceSans,TextSize = 12,TextColor3 = Settings.Theme.Text,TextXAlignment = Enum.TextXAlignment.Left,TextTruncate = Enum.TextTruncate.AtEnd,Text = text,ZIndex = 6,Parent = row})
		end

		line(nil,"Boxes",false,true)
		for _,item in ipairs(LEGEND_NODES) do line(item[1],item[2]) end
		line(nil,"Buttons on a box",false,true)
		for _,item in ipairs(LEGEND_BUTTONS) do line(item[1],item[2]) end
		line(nil,"Arrows",false,true)
		for _,item in ipairs(LEGEND_EDGES) do line(item[1],item[2],true) end
		line(nil,"Outlines: yellow is selected, blue is a search match",false,true)
	end

	
	
	
	function Flowchart.Attach(parent,isActive,pickMode)
		active = isActive or active
		onMode = pickMode

		pane = createSimple("Frame",{
			Name = "Flowchart",
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Size = UDim2.new(1,0,1,0),
			Parent = parent,
		})

		local function toolButton(text,position,size,onClick,tip)
			local btn = Lib.Button.new()
			btn.Text = text
			btn.Position = position
			btn.Size = size
			btn.OnClick:Connect(onClick)
			btn.Gui.Parent = pane
			if tip then Lib.Tooltip.attach(btn.Gui,tip) end
			return btn
		end

		
		local switchWidth = 0
		for _,m in ipairs(MODES) do switchWidth = switchWidth + m[3] + 2 end
		titleButton = toolButton("",UDim2.new(0,2,0,2),UDim2.new(1,-(switchWidth + 6),0,18),showFunctionMenu,"Pick another function to chart")
		titleButton.TextXAlignment = Enum.TextXAlignment.Left
		titleButton.TextTruncate = Enum.TextTruncate.AtEnd
		local x = -switchWidth
		for _,m in ipairs(MODES) do
			local key = m[1]
			modeButtons[key] = toolButton(m[2],UDim2.new(1,x,0,2),UDim2.new(0,m[3],0,18),function()
				if onMode then onMode(key) end
			end,m[4])
			x = x + m[3] + 2
		end

		
		toolButton("Fit",UDim2.new(1,-158,0,23),UDim2.new(0,40,0,18),fit,"Fit the whole graph in the pane (F)")
		toolButton("-",UDim2.new(1,-116,0,23),UDim2.new(0,24,0,18),function() zoomAt(1/1.25) end,"Zoom out (mouse wheel)")
		toolButton("+",UDim2.new(1,-90,0,23),UDim2.new(0,24,0,18),function() zoomAt(1.25) end,"Zoom in (mouse wheel)")
		searchBox = createSimple("TextBox",{
			BackgroundColor3 = Settings.Theme.TextBox,
			BorderColor3 = Settings.Theme.Outline3,
			ClearTextOnFocus = false,
			Font = Enum.Font.SourceSans,
			TextSize = 14,
			TextColor3 = Settings.Theme.Text,
			PlaceholderText = "Search the boxes (Enter: next match)",
			PlaceholderColor3 = Settings.Theme.ReadOnlyText,
			Text = "",
			TextXAlignment = Enum.TextXAlignment.Left,
			Position = UDim2.new(0,2,0,23),
			Size = UDim2.new(1,-230,0,18),
			Parent = pane,
		})
		createSimple("UIPadding",{PaddingLeft = UDim.new(0,4),Parent = searchBox})
		searchCount = createSimple("TextLabel",{
			BackgroundTransparency = 1,
			Font = Enum.Font.SourceSans,
			TextSize = 13,
			TextColor3 = Settings.Theme.ReadOnlyText,
			TextXAlignment = Enum.TextXAlignment.Right,
			Text = "",
			Position = UDim2.new(1,-226,0,23),
			Size = UDim2.new(0,64,0,18),
			Parent = pane,
		})
		toolButton("Legend",UDim2.new(1,-62,0,23),UDim2.new(0,60,0,18),function()
			if not legend then buildLegend() end
			legend.Visible = not legend.Visible
		end,"What the colours of the boxes, arrows and buttons mean")

		searchBox:GetPropertyChangedSignal("Text"):Connect(function() runSearch(true) end)
		searchBox.FocusLost:Connect(function(enterPressed)
			if enterPressed then nextMatch(1) end
		end)

		viewport = createSimple("Frame",{
			Name = "Viewport",
			BackgroundColor3 = Settings.Theme.Syntax.Background,
			BorderSizePixel = 0,
			ClipsDescendants = true,
			Position = UDim2.new(0,0,0,HEADER_H),
			Size = UDim2.new(1,0,1,-HEADER_H),
			Parent = pane,
		})
		
		panFrame = createSimple("Frame",{BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.fromOffset(0,0), Parent = viewport})
		canvas = createSimple("Frame",{BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.fromOffset(10,10), Parent = panFrame})
		uiScale = createSimple("UIScale",{Parent = canvas})
		edgeLayer = createSimple("Frame",{Name = "Edges", BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1,0,1,0), ZIndex = 1, Parent = canvas})
		nodeLayer = createSimple("Frame",{Name = "Nodes", BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1,0,1,0), ZIndex = 2, Parent = canvas})
		labelLayer = createSimple("Frame",{Name = "Labels", BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1,0,1,0), ZIndex = 3, Parent = canvas})

		infoLabel = createSimple("TextLabel",{
			BackgroundTransparency = 1,
			Position = UDim2.new(0,6,1,-16),
			Size = UDim2.new(1,-12,0,14),
			Font = Enum.Font.SourceSans,
			TextSize = 12,
			TextColor3 = Settings.Theme.ReadOnlyText,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			ZIndex = 5,
			Parent = viewport,
		})
		
		emptyLabel = createSimple("TextLabel",{
			BackgroundTransparency = 1,
			Size = UDim2.new(1,0,1,0),
			Font = Enum.Font.SourceSans,
			TextSize = 14,
			TextColor3 = Settings.Theme.ReadOnlyText,
			TextWrapped = true,
			Text = "",
			ZIndex = 5,
			Parent = viewport,
		})

		viewport:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			if pendingFit then fit() end
		end)

		
		
		local uis = service.UserInputService
		local mouse = Main.Mouse
		local function dragButton(input)
			return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.MouseButton3
		end
		Main.Track(uis.InputBegan:Connect(function(input)
			if not dragButton(input) or not active() or not Lib.CheckMouseInGui(viewport) then return end
			panning = true
			panMoved = 0
			panStart = Vector2.new(mouse.X,mouse.Y)
			panOrigin = Vector2.new(panX,panY)
		end))
		Main.Track(uis.InputChanged:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseMovement then
				if not panning then return end
				local delta = Vector2.new(mouse.X,mouse.Y) - panStart
				panMoved = math.max(panMoved,delta.Magnitude)
				if panMoved > 3 then
					panX,panY = panOrigin.X+delta.X,panOrigin.Y+delta.Y
					applyView()
				end
			elseif input.UserInputType == Enum.UserInputType.MouseWheel then
				if not active() or not Lib.CheckMouseInGui(viewport) then return end
				local pos = viewport.AbsolutePosition
				zoomAt(input.Position.Z > 0 and 1.15 or 1/1.15,mouse.X-pos.X,mouse.Y-pos.Y)
			end
		end))
		Main.Track(uis.InputEnded:Connect(function(input)
			if dragButton(input) then panning = false end
		end))
	end

	
	function Flowchart.SetMode(mode)
		for key,button in pairs(modeButtons) do
			button.TextColor3 = key == mode and SELECTED or Settings.Theme.Text
			button.Font = key == mode and Enum.Font.SourceSansBold or Enum.Font.SourceSans
		end
	end

	
	
	
	
	function Flowchart.Show(G,options)
		if not pane then return end
		opts = options or {}
		graph = G
		if not G.w then Analysis.Layout(G,measure) end

		titleButton.Text = " "..(opts.Title or "")
		emptyLabel.Text = ""
		local info = ("%d nodes"):format(#G.nodes)
		if G.truncated then info = info.." (large function, graph cut short)" end
		if G.hidden and G.hidden > 0 then info = info..(", %d functions without static calls not shown"):format(G.hidden) end
		infoLabel.Text = info.."   |   drag to pan, wheel to zoom, click a box to jump to its code"

		render()

		viewKey = opts.ViewKey
		local saved = viewKey and views[viewKey]
		if saved then
			zoom,panX,panY = saved.zoom,saved.panX,saved.panY
			applyView()
		else
			fit()
		end
	end

	
	function Flowchart.Clear(message)
		if not pane then return end
		graph,opts,viewKey = nil,{},nil
		for _,layer in ipairs({edgeLayer,nodeLayer,labelLayer}) do
			layer:ClearAllChildren()
		end
		nodeFrames,selectedId = {},nil
		matchSet,matchList,matchIdx = {},{},0
		searchCount.Text = ""
		titleButton.Text = ""
		infoLabel.Text = ""
		emptyLabel.Text = message or ""
	end

	
	function Flowchart.Highlight(id,doReveal)
		if not pane or not graph or id == selectedId then return end
		setSelected(id)
		local nd = id and graph.nodes[id]
		if nd and doReveal then reveal(nd) end
	end

	function Flowchart.GetGraph()
		return graph
	end

	
	function Flowchart.Mark(ids)
		if not pane or not graph then return end
		matchSet,matchList,matchIdx = {},{},0
		for id in pairs(ids) do
			local nd = graph.nodes[id]
			if nd then
				matchSet[id] = true
				matchList[#matchList+1] = nd
			end
		end
		table.sort(matchList,function(a,b) return a.id < b.id end)
		for id in pairs(nodeFrames) do applyStroke(id) end
		searchCount.Text = #matchList.." marked"
	end

	return Flowchart
end

return {InitDeps = initDeps, InitAfterMain = initAfterMain, Main = main}

end,
["Lib"] = function()



local Main,Apps,Settings 
local Explorer 
local API,RMD,env,service,plr,create,createSimple 

local function initDeps(data)
	Main = data.Main
	Apps = data.Apps
	Settings = data.Settings

	API = data.API
	RMD = data.RMD
	env = data.env
	service = data.service
	plr = data.plr
	create = data.create
	createSimple = data.createSimple
end

local function initAfterMain()
	Explorer = Apps.Explorer
end

local function main()
	local Lib = {}

	local renderStepped = service.RunService.RenderStepped
	local signalWait = renderStepped.wait
	local PH = newproxy() 
	local SIGNAL = newproxy()

	
	local function initObj(props,mt)
		local type = type
		local function copy(t)
			local res = {}
			for i,v in pairs(t) do
				if v == SIGNAL then
					res[i] = Lib.Signal.new()
				elseif type(v) == "table" then
					res[i] = copy(v)
				else
					res[i] = v
				end
			end		
			return res
		end

		local newObj = copy(props)
		return setmetatable(newObj,mt)
	end

	local function getGuiMT(props,funcs)
		return {__index = function(self,ind) if not props[ind] then return funcs[ind] or self.Gui[ind] end end,
		__newindex = function(self,ind,val) if not props[ind] then self.Gui[ind] = val else rawset(self,ind,val) end end}
	end

	

	Lib.FormatLuaString = (function()
		local string = string
		local gsub = string.gsub
		local format = string.format
		local char = string.char
		local cleanTable = {['"'] = '\\"', ['\\'] = '\\\\'}
		for i = 0,31 do
			cleanTable[char(i)] = "\\"..format("%03d",i)
		end
		for i = 127,255 do
			cleanTable[char(i)] = "\\"..format("%03d",i)
		end

		return function(str)
			return gsub(str,"[\"\\\0-\31\127-\255]",cleanTable)
		end
	end)()

	
	Lib.LuaKeywords = {}
	for word in ("and break do else elseif end false for function goto if in local nil not or repeat return then true until while"):gmatch("%a+") do
		Lib.LuaKeywords[word] = true
	end

	Lib.CheckMouseInGui = function(gui)
		if gui == nil then return false end
		local mouse = Main.Mouse
		local guiPosition = gui.AbsolutePosition
		local guiSize = gui.AbsoluteSize	

		return mouse.X >= guiPosition.X and mouse.X < guiPosition.X + guiSize.X and mouse.Y >= guiPosition.Y and mouse.Y < guiPosition.Y + guiSize.Y
	end

	Lib.IsShiftDown = function()
		return service.UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) or service.UserInputService:IsKeyDown(Enum.KeyCode.RightShift)
	end

	Lib.IsCtrlDown = function()
		return service.UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or service.UserInputService:IsKeyDown(Enum.KeyCode.RightControl)
	end

	
	Lib.CreateArrow = function(size,num,dir)
		local horizontal = dir == "left" or dir == "right"
		local forward = dir == "down" or dir == "right" 
		local arrowFrame = createSimple("Frame",{
			BackgroundTransparency = 1,
			Name = "Arrow",
			Size = UDim2.new(0,size,0,size)
		})
		if not horizontal and dir ~= "up" and dir ~= "down" then error("r u ok") end

		local half = math.floor(size/2)
		local back = math.floor(num/2)
		for i = 1,num do
			local along = forward and half-i+back+1 or half+i-back-1 
			local across = half-(i-1) 
			local length = i+(i-1)
			createSimple("Frame",{
				BackgroundColor3 = Color3.new(220/255,220/255,220/255),
				BorderSizePixel = 0,
				Position = horizontal and UDim2.new(0,along,0,across) or UDim2.new(0,across,0,along),
				Size = horizontal and UDim2.new(0,1,0,length) or UDim2.new(0,length,0,1),
				Parent = arrowFrame
			})
		end
		return arrowFrame
	end

	Lib.ParseXML = (function()
		
		
		local slashchar = string.byte('/', 1)

		return function(s)
			
			s = s:gsub('<!%-%-(.-)%-%->', '')

			local t, l = {}, {}

			local addtext = function(txt)
				txt = txt:match'^%s*(.*%S)' or ''
				if #txt ~= 0 then
					t[#t+1] = {text=txt}
				end
			end

			s:gsub('<([?!/]?)([-:_%w]+)%s*(/?>?)([^<]*)', function(type, name, closed, txt)
				
				if #type == 0 then
					local a = {}
					if #closed == 0 then
						local len = 0
						for all,aname,_,value,starttxt in string.gmatch(txt, "(.-([-_%w]+)%s*=%s*(.)(.-)%3%s*(/?>?))") do
							len = len + #all
							a[aname] = value
							if #starttxt ~= 0 then
								txt = txt:sub(len+1)
								closed = starttxt
								break
							end
						end
					end
					t[#t+1] = {tag=name, attrs=a, children={}}

					if closed:byte(1) ~= slashchar then
						l[#l+1] = t
						t = t[#t].children
					end

					addtext(txt)
				
				elseif '/' == type then
					t = l[#l]
					l[#l] = nil

					addtext(txt)
				end
			end)

			return {children=t}
		end
	end)()

	Lib.FastWait = function(s)
		if not s then return signalWait(renderStepped) end
		local start = tick()
		while tick() - start < s do signalWait(renderStepped) end
	end

	Lib.ButtonAnim = function(button,data)
		local holding = false
		local disabled = false
		local mode = data and data.Mode or 1
		local control = {}

		if mode == 2 then
			local lerpTo = data.LerpTo or Color3.new(0,0,0)
			local delta = data.LerpDelta or 0.2
			control.StartColor = data.StartColor or button.BackgroundColor3
			control.PressColor = data.PressColor or control.StartColor:lerp(lerpTo,delta)
			control.HoverColor = data.HoverColor or control.StartColor:lerp(control.PressColor,0.6)
			control.OutlineColor = data.OutlineColor
		end

		button.InputBegan:Connect(function(input)
			if disabled then return end

			if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
				if not holding then
					if mode == 1 then
						button.BackgroundTransparency = 0.4
					elseif mode == 2 then
						button.BackgroundColor3 = control.HoverColor
					end
				end
			elseif input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				holding = true
				if mode == 1 then
					button.BackgroundTransparency = 0
				elseif mode == 2 then
					button.BackgroundColor3 = control.PressColor
					if control.OutlineColor then button.BorderColor3 = control.PressColor end
				end
			end
		end)

		button.InputEnded:Connect(function(input)
			if disabled then return end

			if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
				if not holding then
					if mode == 1 then
						button.BackgroundTransparency = 1
					elseif mode == 2 then
						button.BackgroundColor3 = control.StartColor
					end
				end
			elseif input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				holding = false
				if mode == 1 then
					button.BackgroundTransparency = Lib.CheckMouseInGui(button) and 0.4 or 1
				elseif mode == 2 then
					button.BackgroundColor3 = Lib.CheckMouseInGui(button) and control.HoverColor or control.StartColor
					if control.OutlineColor then button.BorderColor3 = control.OutlineColor end
				end
			end
		end)

		control.Disable = function()
			disabled = true
			holding = false

			if mode == 1 then
				button.BackgroundTransparency = 1
			elseif mode == 2 then
				button.BackgroundColor3 = control.StartColor
			end
		end

		control.Enable = function()
			disabled = false
		end

		return control
	end

	Lib.FindAndRemove = function(t,item)
		local pos = table.find(t,item)
		if pos then table.remove(t,pos) end
	end

	Lib.AttachTo = function(obj,data)
		local target,posOffX,posOffY,sizeOffX,sizeOffY,resize,con
		local disabled = false

		local function update()
			if not obj or not target then return end

			local targetPos = target.AbsolutePosition
			local targetSize = target.AbsoluteSize
			obj.Position = UDim2.new(0,targetPos.X + posOffX,0,targetPos.Y + posOffY)
			if resize then obj.Size = UDim2.new(0,targetSize.X + sizeOffX,0,targetSize.Y + sizeOffY) end
		end

		local function setup(o,data)
			obj = o
			data = data or {}
			target = data.Target
			posOffX = data.PosOffX or 0
			posOffY = data.PosOffY or 0
			sizeOffX = data.SizeOffX or 0
			sizeOffY = data.SizeOffY or 0
			resize = data.Resize or false

			if con then con:Disconnect() con = nil end
			if target then
				con = target.Changed:Connect(function(prop)
					if not disabled and (prop == "AbsolutePosition" or prop == "AbsoluteSize") then
						update()
					end
				end)
			end

			update()
		end
		setup(obj,data)

		return {
			SetData = function(obj,data)
				setup(obj,data)
			end,
			Enable = function()
				disabled = false
				update()
			end,
			Disable = function()
				disabled = true
			end,
			Destroy = function()
				if con then con:Disconnect() end
				con = nil
			end,
		}
	end

	Lib.ShowGui = Main.SecureGui

	Lib.ColorToBytes = function(col)
		local round = math.round
		return string.format("%d, %d, %d",round(col.r*255),round(col.g*255),round(col.b*255))
	end

	
	
	
	
	Lib.ToLua = (function()
		local write
		local MAX_DEPTH, MAX_FIELDS = 8, 500

		
		
		local function num(n, single)
			if n ~= n then return "0/0" end
			if n == math.huge then return "math.huge" elseif n == -math.huge then return "-math.huge" end
			if n == math.floor(n) and math.abs(n) < 1e15 then return string.format("%d", n) end
			for digits = single and 6 or 15, single and 9 or 17 do
				local text = string.format("%."..digits.."g", n)
				local back = tonumber(text)
				if single and back then back = string.unpack("f", string.pack("f", back)) end
				if back == n then return text end
			end
			return string.format("%.17g", n)
		end

		local function left(what)
			return "nil --[["..tostring(what):gsub("%]%]", "] ]").."]]", false
		end

		local function call(name, ...)
			local parts, exact = {...}, true
			for i,v in ipairs(parts) do
				if type(v) ~= "string" then
					local ok
					parts[i], ok = write(v)
					exact = exact and ok
				end
			end
			return name.."("..table.concat(parts, ", ")..")", exact
		end

		local function keypoints(name, list, each)
			local parts, exact = {}, true
			for i,kp in ipairs(list) do
				local ok
				parts[i], ok = each(kp)
				exact = exact and ok
			end
			return name..".new({"..table.concat(parts, ", ").."})", exact
		end

		local writers = {
			["nil"] = function() return "nil", true end,
			boolean = function(v) return tostring(v), true end,
			number = function(v) return num(v), true end,
			string = function(v) return '"'..Lib.FormatLuaString(v)..'"', true end,
			Vector2 = function(v) return call("Vector2.new", num(v.X, true), num(v.Y, true)) end,
			Vector3 = function(v) return call("Vector3.new", num(v.X, true), num(v.Y, true), num(v.Z, true)) end,
			Vector2int16 = function(v) return call("Vector2int16.new", num(v.X), num(v.Y)) end,
			Vector3int16 = function(v) return call("Vector3int16.new", num(v.X), num(v.Y), num(v.Z)) end,
			CFrame = function(v)
				local parts = {v:GetComponents()}
				local turned = false 
				for i = 4,12 do
					if parts[i] ~= ((i == 4 or i == 8 or i == 12) and 1 or 0) then turned = true end
				end
				for i,p in ipairs(parts) do parts[i] = num(p, true) end
				return "CFrame.new("..table.concat(parts, ", ", 1, turned and 12 or 3)..")", true
			end,
			Color3 = function(v)
				local r,g,b = v.R*255, v.G*255, v.B*255
				if math.abs(r - math.round(r)) < 1e-3 and math.abs(g - math.round(g)) < 1e-3 and math.abs(b - math.round(b)) < 1e-3 then
					return ("Color3.fromRGB(%d, %d, %d)"):format(math.round(r), math.round(g), math.round(b)), true
				end
				return call("Color3.new", num(v.R, true), num(v.G, true), num(v.B, true))
			end,
			BrickColor = function(v) return call("BrickColor.new", '"'..Lib.FormatLuaString(v.Name)..'"') end,
			UDim = function(v) return call("UDim.new", num(v.Scale, true), num(v.Offset)) end,
			UDim2 = function(v) return call("UDim2.new", num(v.X.Scale, true), num(v.X.Offset), num(v.Y.Scale, true), num(v.Y.Offset)) end,
			EnumItem = function(v) return tostring(v), true end,
			Enum = function(v) return "Enum."..tostring(v):gsub("^Enum%.", ""), true end,
			Enums = function() return "Enum", true end,
			NumberRange = function(v) return call("NumberRange.new", num(v.Min, true), num(v.Max, true)) end,
			NumberSequenceKeypoint = function(v) return call("NumberSequenceKeypoint.new", num(v.Time, true), num(v.Value, true), num(v.Envelope, true)) end,
			ColorSequenceKeypoint = function(v) return call("ColorSequenceKeypoint.new", num(v.Time, true), v.Value) end,
			NumberSequence = function(v) return keypoints("NumberSequence", v.Keypoints, write) end,
			ColorSequence = function(v) return keypoints("ColorSequence", v.Keypoints, write) end,
			Rect = function(v) return call("Rect.new", num(v.Min.X, true), num(v.Min.Y, true), num(v.Max.X, true), num(v.Max.Y, true)) end,
			Ray = function(v) return call("Ray.new", v.Origin, v.Direction) end,
			Region3 = function(v) return call("Region3.new", v.CFrame.Position - v.Size/2, v.CFrame.Position + v.Size/2) end,
			TweenInfo = function(v) return call("TweenInfo.new", num(v.Time, true), v.EasingStyle, v.EasingDirection, num(v.RepeatCount), v.Reverses, num(v.DelayTime, true)) end,
			PhysicalProperties = function(v) return call("PhysicalProperties.new", num(v.Density, true), num(v.Friction, true), num(v.Elasticity, true), num(v.FrictionWeight, true), num(v.ElasticityWeight, true)) end,
			Font = function(v) return call("Font.new", '"'..Lib.FormatLuaString(v.Family)..'"', v.Weight, v.Style) end,
			DateTime = function(v) return call("DateTime.fromUnixTimestampMillis", num(v.UnixTimestampMillis)) end,
			buffer = function(v) return call("buffer.fromstring", '"'..Lib.FormatLuaString(buffer.tostring(v))..'"') end,
			Faces = function(v)
				local parts = {}
				for _,face in ipairs({"Top", "Bottom", "Left", "Right", "Back", "Front"}) do
					if v[face] then parts[#parts+1] = "Enum.NormalId."..face end
				end
				return "Faces.new("..table.concat(parts, ", ")..")", true
			end,
			Axes = function(v)
				local parts = {}
				for _,axis in ipairs({"X", "Y", "Z"}) do
					if v[axis] then parts[#parts+1] = "Enum.Axis."..axis end
				end
				return "Axes.new("..table.concat(parts, ", ")..")", true
			end,
			Instance = function(v)
				local ok, path = pcall(function()
					if v ~= game and not v:IsDescendantOf(game) then return nil end
					return Explorer.GetInstancePath(v)
				end)
				if not ok or not path then
					local okName, name = pcall(function() return v.ClassName..' "'..v.Name..'"' end)
					return left((okName and name or "an instance")..": not in the game")
				end
				return path, true
			end,
		}

		writers.table = function(t, indent, seen, depth)
			if seen[t] then return left("a table that contains itself") end
			if depth > MAX_DEPTH then return left("a table (deeper levels are left out)") end
			if next(t) == nil then return "{}", true end
			seen[t] = true

			local inner = indent.."\t"
			local parts, exact, plain = {}, true, true
			local n = #t
			for i = 1,math.min(n, MAX_FIELDS) do
				local text, ok = write(t[i], inner, seen, depth + 1)
				parts[#parts+1], exact = text, exact and ok
				if type(t[i]) == "table" or not ok then plain = false end
			end

			local keys = {}
			for k in pairs(t) do
				if not (type(k) == "number" and k >= 1 and k <= n and k == math.floor(k)) then keys[#keys+1] = k end
			end
			
			table.sort(keys, function(a, b)
				local ta, tb = type(a), type(b)
				if ta ~= tb then return ta == "string" or (tb ~= "string" and ta < tb) end
				if ta == "string" or ta == "number" then return a < b end
				return tostring(a) < tostring(b)
			end)
			for i,k in ipairs(keys) do
				if #parts >= MAX_FIELDS then break end
				local key, keyOk
				if type(k) == "string" and k:match("^[%a_][%w_]*$") and not Lib.LuaKeywords[k] then
					key, keyOk = k, true
				else
					key, keyOk = write(k, inner, seen, depth + 1)
					key = "["..key.."]"
				end
				local text, ok = write(t[k], inner, seen, depth + 1)
				parts[#parts+1], exact = key.." = "..text, exact and ok and keyOk
			end
			seen[t] = nil 

			local total = n + #keys
			if total > MAX_FIELDS then
				parts[#parts+1] = "nil --[["..(total - MAX_FIELDS).." more fields are left out]]"
				exact, plain = false, false
			end
			
			if plain and #keys == 0 then
				local line = "{"..table.concat(parts, ", ").."}"
				if #line <= 100 then return line, exact end
			end
			return "{\n"..inner..table.concat(parts, ",\n"..inner)..",\n"..indent.."}", exact
		end

		write = function(value, indent, seen, depth)
			local kind = typeof(value)
			local writer = writers[kind]
			if not writer then
				local ok, shown = pcall(tostring, value)
				return left(kind..(ok and shown ~= kind and (": "..shown) or ""))
			end
			local ok, text, exact = pcall(writer, value, indent or "", seen or {}, depth or 1)
			if not ok then return left(kind.." (could not be read)") end
			return text, exact
		end

		return function(value, indent)
			return write(value, indent or "", {}, 1)
		end
	end)()

	Lib.ReadFile = function(filename)
		if not env.readfile then return end

		local s,contents = pcall(env.readfile,filename)
		if s and contents then return contents end
	end

	local saveAsWindow 
	local currentclickhandler = function() end
	Lib.SaveAsPrompt = function(filename, codeToSave, ext)
		local win = saveAsWindow
		if not win then
			win = Lib.Window.new()
			win.Alignable = false
			win.Resizable = false
			win:SetTitle("Save As")
			win:SetSize(300,95)

			local saveButton = Lib.Button.new()
			local nameLabel = Lib.Label.new()
			nameLabel.Text = "Name"
			nameLabel.Position = UDim2.new(0,30,0,10)
			nameLabel.Size = UDim2.new(0,40,0,20)
			win:Add(nameLabel)

			local nameBox = Lib.ViewportTextBox.new()
			nameBox.Position = UDim2.new(0,75,0,10)
			nameBox.Size = UDim2.new(0,220,0,20)
			win:Add(nameBox,"NameBox")

			nameBox.TextBox:GetPropertyChangedSignal("Text"):Connect(function()
				saveButton:SetDisabled(#nameBox:GetText() == 0)
			end)

			local errorLabel = Lib.Label.new()
			errorLabel.Text = ""
			errorLabel.Position = UDim2.new(0,5,1,-45)
			errorLabel.Size = UDim2.new(1,-10,0,20)
			errorLabel.TextColor3 = Settings.Theme.Important
			win.ErrorLabel = errorLabel
			win:Add(errorLabel,"Error")

			local cancelButton = Lib.Button.new()
			cancelButton.AnchorPoint = Vector2.new(1,1)
			cancelButton.Text = "Cancel"
			cancelButton.Position = UDim2.new(1,-5,1,-5)
			cancelButton.Size = UDim2.new(0.5,-10,0,20)
			cancelButton.OnClick:Connect(function()
				win:Close()
			end)
			win:Add(cancelButton)

			saveButton.Text = "Save"
			saveButton.AnchorPoint = Vector2.new(0,1)
			saveButton.Position = UDim2.new(0,5,1,-5)
			saveButton.Size = UDim2.new(0.5,-5,0,20)
			saveButton.OnClick:Connect(function()
				currentclickhandler()
			end)

			win:Add(saveButton,"SaveButton")

			saveAsWindow = win
		end

		currentclickhandler = function()
			if type(codeToSave) == "string" then
				filename = (win.Elements.NameBox.TextBox.Text ~= "" and win.Elements.NameBox.TextBox.Text) or filename
				local extension = ext or filename:match("%.([^%.]+)$") or "txt"
				filename = filename:gsub("%.[^.]+$", "") .. "." .. extension

				local codeText = codeToSave or ""
				if env.writefile then
					local s, msg = pcall(env.writefile, filename, codeText)
					if not s then
						win.Elements.Error.Text = "Error: " .. msg
						Main.Notify("Couldn't save "..filename..": "..tostring(msg), "error")
						task.wait(1)
					else
						Main.Notify("Saved "..filename.." (in your executor's workspace folder)", "success")
					end
				else
					win.Elements.Error.Text = "Your executor does not support 'writefile'"
					task.wait(1)
				end
			elseif type(codeToSave) == "function" then
				filename = (win.Elements.NameBox.TextBox.Text ~= "" and win.Elements.NameBox.TextBox.Text) or filename

				local s, msg = pcall(codeToSave,filename) 
				if not s then
					win.Elements.Error.Text = "Error: " .. msg
					Main.Notify("Couldn't save "..filename..": "..tostring(msg), "error")
					Lib.FastWait(1)
				end
			end
			win:Close()
		end

		win:SetTitle("Save As")
		win.Elements.Error.Text = ""
		win.Elements.NameBox:SetText(filename or "")
		
		win.Elements.SaveButton:SetDisabled(#win.Elements.NameBox:GetText() == 0)

		win:Show()
		repeat task.wait() until win.Closed
	end

	
	Lib.SaveObjectPrompt = function(obj)
		Lib.SaveAsPrompt("Place_"..game.PlaceId.."_"..obj.ClassName.."_"..obj.Name.."_"..os.time(), function(filename)
			local toast = Main.Notify("Saving "..obj.Name.."...", "info", {Persist = true})
			local ok, result = pcall(env.saveinstance, obj, filename, {Decompile = true, RemovePlayerCharacters = false})
			if ok then
				toast:Set("Saved "..obj.Name.." as "..filename.." (in your executor's workspace folder)", "success")
			else
				toast:Set("Couldn't save "..obj.Name..": "..tostring(result), "error", {Details = tostring(result)})
			end
		end)
	end

	

	Lib.Signal = (function()
		local funcs = {}

		local disconnect = function(con)
			local pos = table.find(con.Signal.Connections,con)
			if pos then table.remove(con.Signal.Connections,pos) end
		end

		funcs.Connect = function(self,func)
			if type(func) ~= "function" then error("Attempt to connect a non-function") end		
			local con = {
				Signal = self,
				Func = func,
				Disconnect = disconnect
			}
			self.Connections[#self.Connections+1] = con
			return con
		end

		funcs.Fire = function(self,...)
			for i,v in next,self.Connections do
				xpcall(coroutine.wrap(v.Func),function(e) warn(e.."\n"..debug.traceback()) end,...)
			end
		end

		local mt = {
			__index = funcs,
			__tostring = function(self)
				return "Signal: " .. tostring(#self.Connections) .. " Connections"
			end
		}

		local function new()
			local obj = {}
			obj.Connections = {}

			return setmetatable(obj,mt)
		end

		return {new = new}
	end)()

	Lib.Set = (function()
		local funcs = {}

		funcs.Add = function(self,obj)
			if self.Map[obj] then return end

			local list = self.List
			list[#list+1] = obj
			self.Map[obj] = true
			self.Changed:Fire()
		end

		funcs.Remove = function(self,obj)
			if not self.Map[obj] then return end

			local list = self.List
			local pos = table.find(list,obj)
			if pos then table.remove(list,pos) end
			self.Map[obj] = nil
			self.Changed:Fire()
		end

		funcs.Set = function(self,obj)
			if #self.List == 1 and self.List[1] == obj then return end

			self.List = {obj}
			self.Map = {[obj] = true}
			self.Changed:Fire()
		end

		
		funcs.SetTable = function(self,t)
			local newList,newMap = {},{}
			self.List,self.Map = newList,newMap
			for i = 1,#t do
				local item = t[i]
				if not newMap[item] then
					newMap[item] = true
					newList[#newList+1] = item
				end
			end
			self.Changed:Fire()
		end

		funcs.Clear = function(self)
			if #self.List == 0 then return end
			self.List = {}
			self.Map = {}
			self.Changed:Fire()
		end

		local mt = {__index = funcs}

		local function new()
			local obj = setmetatable({
				List = {},
				Map = {},
				Changed = Lib.Signal.new()
			},mt)

			return obj
		end

		return {new = new}
	end)()
	
