	Lib.DropDown = (function()
		local props = {
			Gui = PH,
			Anim = PH,
			Context = PH,
			Selected = PH,
			Disabled = false,
			CanBeEmpty = true,
			Options = {},
			GuiElems = {},
			OnSelect = SIGNAL
		}
		local funcs = {}

		funcs.Update = function(self)
			local options = self.Options

			if #options > 0 then
				if not self.Selected then
					if not self.CanBeEmpty then
						self.Selected = options[1]
						self.GuiElems.Label.Text = options[1]
					else
						self.GuiElems.Label.Text = "- Select -"
					end
				else
					self.GuiElems.Label.Text = self.Selected
				end
			else
				self.GuiElems.Label.Text = "- Select -"
			end
		end

		funcs.ShowOptions = function(self)
			local context = self.Context

			context.Width = self.Gui.AbsoluteSize.X
			context.ReverseYOffset = self.Gui.AbsoluteSize.Y
			context:Show(self.Gui.AbsolutePosition.X, self.Gui.AbsolutePosition.Y + context.ReverseYOffset)
		end

		funcs.SetOptions = function(self,opts)
			self.Options = opts

			local context = self.Context
			local options = self.Options
			context:Clear()

			local onClick = function(option) self.Selected = option self.OnSelect:Fire(option) self:Update() end

			if self.CanBeEmpty then
				context:Add({Name = "- Select -", OnClick = function() self.Selected = nil self.OnSelect:Fire(nil) self:Update() end})
			end

			for i = 1,#options do
				context:Add({Name = options[i], OnClick = onClick})
			end

			self:Update()
		end

		funcs.SetSelected = function(self,opt)
			self.Selected = type(opt) == "number" and self.Options[opt] or opt
			self:Update()
		end

		local mt = getGuiMT(props,funcs)

		local function new()
			local f = Instance.new("TextButton")
			f.AutoButtonColor = false
			f.Text = ""
			f.Size = UDim2.new(0,100,0,20)
			f.BackgroundColor3 = Settings.Theme.TextBox
			f.BorderColor3 = Settings.Theme.Outline3

			local label = Lib.Label.new()
			label.Position = UDim2.new(0,2,0,0)
			label.Size = UDim2.new(1,-22,1,0)
			label.TextTruncate = Enum.TextTruncate.AtEnd
			label.Parent = f
			local arrow = create({
				{1,"Frame",{BackgroundTransparency=1,Name="EnumArrow",Position=UDim2.new(1,-16,0,2),Size=UDim2.new(0,16,0,16),}},
				{2,"Frame",{BackgroundColor3=Color3.new(0.86274510622025,0.86274510622025,0.86274510622025),BorderSizePixel=0,Parent={1},Position=UDim2.new(0,8,0,9),Size=UDim2.new(0,1,0,1),}},
				{3,"Frame",{BackgroundColor3=Color3.new(0.86274510622025,0.86274510622025,0.86274510622025),BorderSizePixel=0,Parent={1},Position=UDim2.new(0,7,0,8),Size=UDim2.new(0,3,0,1),}},
				{4,"Frame",{BackgroundColor3=Color3.new(0.86274510622025,0.86274510622025,0.86274510622025),BorderSizePixel=0,Parent={1},Position=UDim2.new(0,6,0,7),Size=UDim2.new(0,5,0,1),}},
			})
			arrow.Parent = f

			local obj = initObj(props,mt)
			obj.Gui = f
			obj.Anim = Lib.ButtonAnim(f,{Mode = 2, StartColor = Settings.Theme.TextBox, LerpTo = Settings.Theme.Button, LerpDelta = 0.15})
			obj.Context = Lib.ContextMenu.new()
			obj.Context.Iconless = true
			obj.Context.MaxHeight = 200
			obj.Selected = nil
			obj.GuiElems = {Label = label}
			f.MouseButton1Down:Connect(function() obj:ShowOptions() end)
			obj:Update()
			return obj
		end

		return {new = new}
	end)()

	Lib.ClickSystem = (function()
		local props = {
			LastItem = PH,
			OnDown = SIGNAL,
			OnRelease = SIGNAL,
			AllowedButtons = {1},
			Combo = 0,
			MaxCombo = 2,
			ComboTime = 0.5,
			Items = {},
			ItemCons = {},
			ClickId = -1,
			LastButton = ""
		}
		local funcs = {}

		funcs.Trigger = function(self, item, button, X, Y)
			if table.find(self.AllowedButtons, button) then
				if self.LastButton ~= button or self.LastItem ~= item or self.Combo == self.MaxCombo or tick() - self.ClickId > self.ComboTime then
					self.Combo = 0
					self.LastButton = button
					self.LastItem = item
				end

				self.Combo = self.Combo + 1
				self.ClickId = tick()

				
				local isTouch = button == 1 and service.UserInputService:GetLastInputType() == Enum.UserInputType.Touch
				if isTouch then task.spawn(function()
					if self.InputDown then
						self.InputDown = false
					else
						self.InputDown = tick()

						item.MouseButton1Up:Once(function()
							self.InputDown = false
						end)

						while self.InputDown and not Explorer.Dragging do
							if (tick() - self.InputDown) >= 0.4 then
								self.InputDown = false
								self["OnRelease"]:Fire(item, self.Combo, 2, Vector2.new(X, Y))
								break
							end;task.wait()
						end
					end
				end) end

				local release
				release = service.UserInputService.InputEnded:Connect(function(input)
					if input.UserInputType == Enum.UserInputType["MouseButton" .. button] then
						release:Disconnect()
						if Lib.CheckMouseInGui(item) and self.LastButton == button and self.LastItem == item then
							self.InputDown = false 
							self["OnRelease"]:Fire(item,self.Combo,button)
						end
					end
				end)

				self["OnDown"]:Fire(item,self.Combo,button)
			end
		end

		funcs.Add = function(self,item)
			if table.find(self.Items,item) then return end

			local cons = {}
			cons[1] = item.MouseButton1Down:Connect(function(X, Y) self:Trigger(item, 1, X, Y) end)
			cons[2] = item.MouseButton2Down:Connect(function(X, Y) self:Trigger(item, 2, X, Y) end)

			self.ItemCons[item] = cons
			self.Items[#self.Items+1] = item
		end

		funcs.Remove = function(self,item)
			local ind = table.find(self.Items,item)
			if not ind then return end

			for i,v in pairs(self.ItemCons[item]) do
				v:Disconnect()
			end
			self.ItemCons[item] = nil
			table.remove(self.Items,ind)
		end

		local mt = {__index = funcs}

		local function new()
			local obj = initObj(props,mt)

			return obj
		end

		return {new = new}
	end)()

	
	
	Lib.Tooltip = (function()
		local DELAY, MAX_WIDTH = 0.45, 280
		local gui, frame, label
		local token = 0

		local function ensure()
			if gui and gui.Parent then return end

			gui = Instance.new("ScreenGui")
			gui.DisplayOrder = Main.DisplayOrders.Tooltip
			gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling

			frame = createSimple("Frame",{BackgroundColor3 = Settings.Theme.Menu, BorderSizePixel = 0, Visible = false, Parent = gui})
			createSimple("UICorner",{CornerRadius = UDim.new(0,4), Parent = frame})
			createSimple("UIStroke",{Color = Settings.Theme.Outline2, Thickness = 1, Parent = frame})
			label = createSimple("TextLabel",{
				BackgroundTransparency = 1,
				Position = UDim2.new(0,6,0,3),
				Font = Enum.Font.SourceSans,
				TextSize = 14,
				TextColor3 = Settings.Theme.Text,
				TextWrapped = true,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextYAlignment = Enum.TextYAlignment.Top,
				Parent = frame,
			})
			Lib.ShowGui(gui)
		end

		local function hide()
			token = token + 1
			if frame then frame.Visible = false end
		end

		local function show(text)
			if type(text) == "function" then
				local ok,result = pcall(text)
				text = ok and result or nil
			end
			if type(text) ~= "string" or text == "" then return end

			ensure()
			local size = service.TextService:GetTextSize(text,14,Enum.Font.SourceSans,Vector2.new(MAX_WIDTH,1000))
			local w,h = math.ceil(size.X) + 14,math.ceil(size.Y) + 8
			label.Text = text
			label.Size = UDim2.new(0,w - 12,0,h - 6)
			frame.Size = UDim2.new(0,w,0,h)

			local mouse = Main.Mouse
			local x,y = mouse.X + 14,mouse.Y + 20
			if x + w > mouse.ViewSizeX then x = math.max(2,mouse.ViewSizeX - w - 2) end
			if y + h > mouse.ViewSizeY then y = math.max(2,mouse.Y - h - 8) end
			frame.Position = UDim2.new(0,x,0,y)
			frame.Visible = true
		end

		local function attach(obj,text)
			if type(obj) == "table" then obj = obj.Gui end

			obj.MouseEnter:Connect(function()
				token = token + 1
				local mine = token
				task.delay(DELAY,function()
					if mine ~= token or not obj.Parent or not Lib.CheckMouseInGui(obj) then return end
					show(text)
				end)
			end)
			obj.MouseLeave:Connect(hide)
			obj.InputBegan:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then hide() end
			end)
		end

		return {attach = attach, hide = hide}
	end)()

	
	
	
	
	Lib.Notify = (function()
		local DURATION = {info = 3.5, success = 3.5, warn = 5.5, error = 9}
		local THEME_KEY = {info = "Info", success = "Success", warn = "Warning", error = "Danger"}
		local WIDTH,MAX_ACTIVE = 400,4
		local gui,holder,loop
		local active = {}
		local order = 0
		local toast = {}
		toast.__index = toast

		local function ensure()
			if gui and gui.Parent then return end

			gui = Instance.new("ScreenGui")
			gui.DisplayOrder = Main.DisplayOrders.Toast
			gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling

			holder = createSimple("Frame",{
				Name = "Toasts",
				AnchorPoint = Vector2.new(0.5,1),
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				Position = UDim2.new(0.5,0,1,-16),
				Size = UDim2.new(0,WIDTH,0,0),
				AutomaticSize = Enum.AutomaticSize.Y,
				Parent = gui,
			})
			createSimple("UIListLayout",{
				Padding = UDim.new(0,6),
				SortOrder = Enum.SortOrder.LayoutOrder,
				HorizontalAlignment = Enum.HorizontalAlignment.Center,
				VerticalAlignment = Enum.VerticalAlignment.Bottom,
				Parent = holder,
			})
			Lib.ShowGui(gui)
		end

		
		local function render(t)
			local text = t.Count > 1 and (t.Text.."  (x"..t.Count..")") or t.Text
			local textSize = service.TextService:GetTextSize(text,14,Enum.Font.SourceSans,Vector2.new(WIDTH - 26,1000))
			local textH = math.ceil(textSize.Y)

			t.Accent.BackgroundColor3 = Settings.Theme[THEME_KEY[t.Kind]]
			t.Label.Text = text
			t.Label.Size = UDim2.new(1,-22,0,textH)
			t.Hint.Text = t.HintText or ""
			t.Hint.Visible = t.CanCopy
			t.Frame.Size = UDim2.new(1,0,0,textH + 14 + (t.CanCopy and 13 or 0))
		end

		function toast:Close()
			if self.Closed then return end
			self.Closed = true
			local pos = table.find(active,self)
			if pos then table.remove(active,pos) end

			local ti = TweenInfo.new(0.2)
			local tweens = service.TweenService
			tweens:Create(self.Frame,ti,{BackgroundTransparency = 1}):Play()
			tweens:Create(self.Label,ti,{TextTransparency = 1}):Play()
			tweens:Create(self.Hint,ti,{TextTransparency = 1}):Play()
			tweens:Create(self.Accent,ti,{BackgroundTransparency = 1}):Play()
			tweens:Create(self.Stroke,ti,{Transparency = 1}):Play()
			task.delay(0.25,function() self.Frame:Destroy() end)
		end

		function toast:Set(text,kind,opts)
			opts = opts or {}
			self.Text = tostring(text)
			self.BaseText = self.Text
			self.Kind = THEME_KEY[kind] and kind or self.Kind
			self.Count = 1
			self.Details = opts.Details
			self.Persist = opts.Persist or false
			self.Duration = opts.Duration or DURATION[self.Kind]
			self.Left = self.Duration
			self.CanCopy = env.setclipboard ~= nil and (opts.Details ~= nil or self.Kind == "error")
			self.HintText = self.CanCopy and "Click to copy the details" or nil
			render(self)
		end

		local function startLoop()
			if loop then return end
			loop = service.RunService.Heartbeat:Connect(function(dt)
				for i = #active,1,-1 do
					local t = active[i]
					if not t.Persist and not t.Hover then
						t.Left = t.Left - dt
						if t.Left <= 0 then t:Close() end
					end
				end
				if #active == 0 then
					Lib.FindAndRemove(Main.Connections,loop) 
					loop:Disconnect()
					loop = nil
				end
			end)
			Main.Track(loop)
		end

		local function show(text,kind,opts)
			text = tostring(text)
			kind = THEME_KEY[kind] and kind or "info"
			opts = opts or {}
			ensure()

			
			local last = active[#active]
			if last and not last.Persist and not opts.Persist and last.BaseText == text and last.Kind == kind then
				last.Count = last.Count + 1
				last.Left = last.Duration
				render(last)
				return last
			end

			order = order + 1
			local frame = createSimple("TextButton",{
				Name = "Toast",
				AutoButtonColor = false,
				BackgroundColor3 = Settings.Theme.Menu,
				BorderSizePixel = 0,
				Text = "",
				Size = UDim2.new(1,0,0,30),
				LayoutOrder = order,
				Parent = holder,
			})
			createSimple("UICorner",{CornerRadius = UDim.new(0,4),Parent = frame})
			local stroke = createSimple("UIStroke",{Color = Settings.Theme.Outline2,Thickness = 1,Parent = frame})
			local accent = createSimple("Frame",{BorderSizePixel = 0,Size = UDim2.new(0,4,1,0),Parent = frame})
			createSimple("UICorner",{CornerRadius = UDim.new(0,4),Parent = accent})
			local label = createSimple("TextLabel",{
				BackgroundTransparency = 1,
				Position = UDim2.new(0,14,0,6),
				Font = Enum.Font.SourceSans,
				TextSize = 14,
				TextColor3 = Settings.Theme.Text,
				TextWrapped = true,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextYAlignment = Enum.TextYAlignment.Top,
				Parent = frame,
			})
			local hint = createSimple("TextLabel",{
				BackgroundTransparency = 1,
				AnchorPoint = Vector2.new(0,1),
				Position = UDim2.new(0,14,1,-3),
				Size = UDim2.new(1,-22,0,12),
				Font = Enum.Font.SourceSans,
				TextSize = 12,
				TextColor3 = Settings.Theme.ReadOnlyText,
				TextXAlignment = Enum.TextXAlignment.Left,
				Parent = frame,
			})

			local t = setmetatable({Frame = frame,Label = label,Hint = hint,Accent = accent,Stroke = stroke,Kind = kind},toast)
			t:Set(text,kind,opts)

			frame.MouseEnter:Connect(function() t.Hover = true end)
			frame.MouseLeave:Connect(function() t.Hover = false end)
			frame.MouseButton1Click:Connect(function()
				if t.CanCopy and t.HintText ~= "Copied to clipboard" then
					pcall(env.setclipboard,t.Details or t.Text)
					t.HintText = "Copied to clipboard"
					t.Left = math.max(t.Left,2)
					render(t)
				else
					t:Close()
				end
			end)

			active[#active+1] = t
			local i = 1
			while #active > MAX_ACTIVE and active[i] do
				if active[i].Persist then i = i + 1 else active[i]:Close() end 
			end
			startLoop()

			
			if kind == "error" then warn("[OpenDex] "..(opts.Details or text)) end
			return t
		end

		return {show = show}
	end)()

	
	
	Lib.Form = (function()
		local funcs = {}
		local ROW_H,RESET_W = 24,40

		local function textLabel(parent,text,props)
			local l = Instance.new("TextLabel")
			l.BackgroundTransparency = 1
			l.Font = Enum.Font.SourceSans
			l.TextSize = 14
			l.TextColor3 = Settings.Theme.Text
			l.TextXAlignment = Enum.TextXAlignment.Left
			l.TextTruncate = Enum.TextTruncate.AtEnd
			l.Text = text
			for k,v in pairs(props or {}) do l[k] = v end
			l.Parent = parent
			return l
		end

		local function newRow(self,height)
			local row = Instance.new("Frame")
			row.BackgroundTransparency = 1
			row.BorderSizePixel = 0
			row.Size = UDim2.new(1,0,0,height or ROW_H)
			self.Count = self.Count + 1
			row.LayoutOrder = self.Count
			row.Parent = self.Gui
			return row
		end

		local function describe(opts,...)
			if not opts or not opts.Description then return end
			for _,obj in ipairs({...}) do Lib.Tooltip.attach(obj,opts.Description) end
		end

		local function inputBox(row,width,rightPad)
			local box = Instance.new("TextBox")
			box.AnchorPoint = Vector2.new(1,0)
			box.Position = UDim2.new(1,-rightPad,0,2)
			box.Size = UDim2.new(0,width,0,ROW_H - 4)
			box.BackgroundColor3 = Settings.Theme.TextBox
			box.BorderColor3 = Settings.Theme.Outline3
			box.ClearTextOnFocus = false
			box.TextColor3 = Settings.Theme.Text
			box.PlaceholderColor3 = Settings.Theme.PlaceholderText
			box.Font = Enum.Font.SourceSans
			box.TextSize = 14
			box.TextXAlignment = Enum.TextXAlignment.Left
			box.Parent = row
			createSimple("UIPadding",{PaddingLeft = UDim.new(0,4),PaddingRight = UDim.new(0,4),Parent = box})
			return box
		end

		
		local function flash(obj)
			local old = obj.BorderColor3
			obj.BorderColor3 = Settings.Theme.Danger
			task.delay(0.8,function() if obj.Parent then obj.BorderColor3 = old end end)
		end

		
		
		local function addReset(row,opts,get,set)
			if opts.Default == nil then return 4,function() end end

			local btn = Instance.new("TextButton")
			btn.BackgroundTransparency = 1
			btn.AnchorPoint = Vector2.new(1,0)
			btn.Position = UDim2.new(1,-2,0,2)
			btn.Size = UDim2.new(0,RESET_W,0,ROW_H - 4)
			btn.Font = Enum.Font.SourceSans
			btn.TextSize = 13
			btn.TextColor3 = Settings.Theme.Info
			btn.Text = "Reset"
			btn.Visible = false
			btn.Parent = row
			btn.MouseButton1Click:Connect(function() set(opts.Default) end)
			Lib.Tooltip.attach(btn,"Back to the default ("..tostring(opts.Default)..")")
			return RESET_W + 6,function() btn.Visible = get() ~= opts.Default end
		end

		funcs.AddHeading = function(self,text)
			local row = newRow(self,26)
			textLabel(row,text,{Font = Enum.Font.SourceSansBold,TextSize = 16,Size = UDim2.new(1,0,0,22)})
			local line = Instance.new("Frame")
			line.BackgroundColor3 = Settings.Theme.Outline2
			line.BorderSizePixel = 0
			line.Position = UDim2.new(0,0,1,-2)
			line.Size = UDim2.new(1,0,0,1)
			line.Parent = row
			return {Gui = row}
		end

		
		funcs.AddNote = function(self,text,width)
			local size = service.TextService:GetTextSize(text,13,Enum.Font.SourceSans,Vector2.new(width or 220,1000))
			local row = newRow(self,math.ceil(size.Y) + 4)
			textLabel(row,text,{TextSize = 13,TextColor3 = Settings.Theme.ReadOnlyText,TextWrapped = true,TextTruncate = Enum.TextTruncate.None,TextYAlignment = Enum.TextYAlignment.Top,Size = UDim2.new(1,0,1,0)})
			return {Gui = row}
		end

		funcs.AddCheckbox = function(self,text,value,onChange,opts)
			opts = opts or {}
			local row = newRow(self)
			local current = value and true or false
			local box = Lib.Checkbox.new()
			local rightPad,refreshReset

			local function commit(v,silent)
				current = v and true or false
				box:SetState(current)
				refreshReset()
				if onChange and not silent then onChange(current) end
			end
			rightPad,refreshReset = addReset(row,opts,function() return current end,commit)

			box.Gui.Position = UDim2.new(0,2,0,4)
			box.Gui.Parent = row
			box:SetState(current)
			box.OnInput:Connect(function()
				current = box.Toggled
				refreshReset()
				if onChange then onChange(current) end
			end)

			local label = Instance.new("TextButton")
			label.BackgroundTransparency = 1
			label.Position = UDim2.new(0,26,0,0)
			label.Size = UDim2.new(1,-(26 + rightPad),1,0)
			label.Font = Enum.Font.SourceSans
			label.TextSize = 14
			label.TextColor3 = Settings.Theme.Text
			label.TextXAlignment = Enum.TextXAlignment.Left
			label.TextTruncate = Enum.TextTruncate.AtEnd
			label.Text = text
			label.Parent = row
			label.MouseButton1Click:Connect(function() commit(not current) end)

			refreshReset()
			describe(opts,label,box.Gui)
			return {Gui = row,Get = function() return current end,Set = commit}
		end

		
		funcs.AddNumber = function(self,text,value,onChange,opts)
			opts = opts or {}
			local row = newRow(self)
			local current = value
			local rightPad,refreshReset
			local box

			local function format(v)
				if opts.Integer then return tostring(math.floor(v + 0.5)) end
				return tostring(math.floor(v * 1000 + 0.5) / 1000)
			end

			local function commit(v,silent)
				current = v
				box.Text = format(v)
				refreshReset()
				if onChange and not silent then onChange(v) end
			end
			rightPad,refreshReset = addReset(row,opts,function() return current end,commit)

			local label = textLabel(row,text,{Size = UDim2.new(1,-(rightPad + (opts.Width or 70) + 8),1,0)})
			box = inputBox(row,opts.Width or 70,rightPad)
			box.Text = format(current)

			box.FocusLost:Connect(function()
				local n = tonumber(box.Text)
				if not n or n ~= n or n == math.huge or n == -math.huge then
					box.Text = format(current)
					flash(box)
					Main.Notify(text..": enter a number","warn")
					return
				end
				if opts.Integer then n = math.floor(n + 0.5) end
				local lo,hi = opts.Min or -math.huge,opts.Max or math.huge
				if n < lo or n > hi then
					n = math.clamp(n,lo,hi)
					flash(box)
					Main.Notify(("%s must be between %s and %s, using %s"):format(text,tostring(opts.Min or "-inf"),tostring(opts.Max or "inf"),format(n)),"warn")
				end
				commit(n)
			end)

			refreshReset()
			describe(opts,label,box)
			return {Gui = row,Get = function() return current end,Set = commit}
		end

		
		funcs.AddInput = function(self,text,value,onChange,opts)
			opts = opts or {}
			local row = newRow(self)
			local current = value
			local rightPad,refreshReset
			local box

			local function commit(v,silent)
				current = v
				box.Text = tostring(v)
				refreshReset()
				if onChange and not silent then onChange(v) end
			end
			rightPad,refreshReset = addReset(row,opts,function() return current end,commit)

			local label = textLabel(row,text,{Size = UDim2.new(1,-(rightPad + (opts.Width or 140) + 8),1,0)})
			box = inputBox(row,opts.Width or 140,rightPad)
			box.Text = tostring(current)

			box.FocusLost:Connect(function()
				local v = box.Text
				if opts.Validate then
					local ok,result = opts.Validate(v)
					if not ok then
						box.Text = tostring(current)
						flash(box)
						Main.Notify(text..": "..tostring(result),"warn")
						return
					end
					v = result
				end
				commit(v)
			end)

			refreshReset()
			describe(opts,label,box)
			return {Gui = row,Get = function() return current end,Set = commit}
		end

		funcs.AddDropdown = function(self,text,options,value,onChange,opts)
			opts = opts or {}
			local row = newRow(self)
			local current = value
			local rightPad,refreshReset
			local dropdown = Lib.DropDown.new()

			local function commit(v,silent)
				current = v
				dropdown:SetSelected(v)
				refreshReset()
				if onChange and not silent then onChange(v) end
			end
			rightPad,refreshReset = addReset(row,opts,function() return current end,commit)

			local label = textLabel(row,text,{Size = UDim2.new(1,-(rightPad + (opts.Width or 110) + 8),1,0)})
			dropdown.CanBeEmpty = false
			dropdown:SetOptions(options)
			dropdown:SetSelected(current)
			dropdown.Gui.AnchorPoint = Vector2.new(1,0)
			dropdown.Gui.Position = UDim2.new(1,-rightPad,0,2)
			dropdown.Gui.Size = UDim2.new(0,opts.Width or 110,0,ROW_H - 4)
			dropdown.Gui.Parent = row
			dropdown.OnSelect:Connect(function(option)
				current = option
				refreshReset()
				if onChange then onChange(option) end
			end)

			refreshReset()
			describe(opts,label,dropdown.Gui)
			return {Gui = row,Get = function() return current end,Set = commit}
		end

		
		funcs.AddSlider = function(self,text,value,onChange,opts)
			opts = opts or {}
			local lo,hi,step = opts.Min or 0,opts.Max or 1,opts.Step or 0.05
			local trackW = opts.Width or 110
			local row = newRow(self)
			local current = value
			local rightPad,refreshReset
			local format = opts.Format or function(v) return tostring(math.floor(v * 100 + 0.5) / 100) end

			local track = Instance.new("Frame")
			track.AnchorPoint = Vector2.new(1,0.5)
			track.BackgroundColor3 = Settings.Theme.Outline2
			track.BorderSizePixel = 0
			track.Size = UDim2.new(0,trackW,0,4)
			local fill = Instance.new("Frame")
			fill.BackgroundColor3 = Settings.Theme.ListSelection
			fill.BorderSizePixel = 0
			fill.Parent = track
			local thumb = Instance.new("Frame")
			thumb.AnchorPoint = Vector2.new(0.5,0.5)
			thumb.BackgroundColor3 = Settings.Theme.Text
			thumb.BorderSizePixel = 0
			thumb.Size = UDim2.new(0,8,0,14)
			thumb.Parent = track
			createSimple("UICorner",{CornerRadius = UDim.new(0,3),Parent = thumb})
			local valueLabel

			local function commit(v,silent)
				v = math.clamp(math.floor((v - lo) / step + 0.5) * step + lo,lo,hi)
				current = v
				local frac = (hi > lo) and (v - lo) / (hi - lo) or 0
				fill.Size = UDim2.new(frac,0,1,0)
				thumb.Position = UDim2.new(frac,0,0.5,0)
				valueLabel.Text = format(v)
				refreshReset()
				if onChange and not silent then onChange(v) end
			end
			rightPad,refreshReset = addReset(row,opts,function() return current end,commit)

			local label = textLabel(row,text,{Size = UDim2.new(1,-(rightPad + trackW + 58),1,0)})
			valueLabel = textLabel(row,"",{AnchorPoint = Vector2.new(1,0),Position = UDim2.new(1,-rightPad,0,0),Size = UDim2.new(0,44,1,0),TextXAlignment = Enum.TextXAlignment.Right})
			track.Position = UDim2.new(1,-(rightPad + 50),0.5,0)
			track.Parent = row

			
			local hit = Instance.new("TextButton")
			hit.AnchorPoint = Vector2.new(0.5,0.5)
			hit.BackgroundTransparency = 1
			hit.Position = UDim2.new(0.5,0,0.5,0)
			hit.Size = UDim2.new(1,12,0,ROW_H)
			hit.Text = ""
			hit.Parent = track

			local function fromMouse(x)
				local frac = math.clamp((x - track.AbsolutePosition.X) / math.max(1,track.AbsoluteSize.X),0,1)
				commit(lo + frac * (hi - lo))
			end
			hit.InputBegan:Connect(function(input)
				if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
				fromMouse(input.Position.X)
				local uis = service.UserInputService
				local moveCon,endCon
				moveCon = uis.InputChanged:Connect(function(move)
					if move.UserInputType == Enum.UserInputType.MouseMovement or move.UserInputType == Enum.UserInputType.Touch then
						fromMouse(move.Position.X)
					end
				end)
				endCon = uis.InputEnded:Connect(function(finish)
					if finish.UserInputType == Enum.UserInputType.MouseButton1 or finish.UserInputType == Enum.UserInputType.Touch then
						moveCon:Disconnect()
						endCon:Disconnect()
					end
				end)
			end)

			commit(current,true)
			describe(opts,label,hit)
			return {Gui = row,Get = function() return current end,Set = commit}
		end

		
		funcs.AddButton = function(self,text,onClick,opts)
			opts = opts or {}
			local row = newRow(self)
			local button = Lib.Button.new()
			button.Text = text
			button.Position = UDim2.new(0,0,0,2)
			button.Size = UDim2.new(0,opts.Width or 140,0,ROW_H - 4)
			button.OnClick:Connect(function() onClick() end)
			button.Gui.Parent = row
			describe(opts,button.Gui)
			return {Gui = row,Button = button}
		end

		local mt = {__index = funcs}

		local function new(parent)
			local gui = Instance.new("ScrollingFrame")
			gui.BackgroundTransparency = 1
			gui.BorderSizePixel = 0
			gui.Size = UDim2.new(1,0,1,0)
			gui.CanvasSize = UDim2.new(0,0,0,0)
			gui.AutomaticCanvasSize = Enum.AutomaticSize.Y
			gui.ScrollBarThickness = 8
			gui.ScrollBarImageColor3 = Settings.Theme.Highlight
			gui.TopImage = ""
			gui.BottomImage = ""
			createSimple("UIListLayout",{Padding = UDim.new(0,4),SortOrder = Enum.SortOrder.LayoutOrder,Parent = gui})
			createSimple("UIPadding",{PaddingLeft = UDim.new(0,10),PaddingRight = UDim.new(0,12),PaddingTop = UDim.new(0,6),PaddingBottom = UDim.new(0,6),Parent = gui})
			gui.Parent = parent
			return setmetatable({Gui = gui,Count = 0},mt)
		end

		return {new = new}
	end)()

	return Lib
end

return {InitDeps = initDeps, InitAfterMain = initAfterMain, Main = main}
end,
["ModelViewer"] = function()



local Main,Lib,Apps,Settings 
local Explorer 
local env 

local function initDeps(data)
	Main = data.Main
	Lib = data.Lib
	Apps = data.Apps
	Settings = data.Settings

	env = data.env
end

local function initAfterMain()
	Explorer = Apps.Explorer
end

local function getPath(obj)
	if obj.Parent == nil then
		return "Nil parented"
	else
		return Explorer.GetInstancePath(obj)
	end
end

local function main()
	local RunService = game:GetService("RunService")

	local ModelViewer = {
		EnableInputCamera = true,
		IsViewing = false,
		AutoRefresh = false,
		ZoomMultiplier = 2,
		AutoRotate = true,
		RotationSpeed = 0.01,
		RefreshRate = 4 
	}
	
	local window, viewportFrame, pathLabel, settingsButton
	local model, camera, originalModel
	local distance, center = 10, Vector3.zero 
	local refreshLoopRunning = false
	
	
	ModelViewer.StopViewModel = function(updating)
		if updating then
			local existing = viewportFrame:FindFirstChildOfClass("Model")
			if existing then existing:Destroy() end
		else
			if camera then camera = nil end
			if model then model = nil end
			viewportFrame:ClearAllChildren()
			
			ModelViewer.IsViewing = false
			window:SetTitle("3D Preview")
			pathLabel.Gui.Text = ""
		end
	end

	ModelViewer.ViewModel = function(item, updating)
		if not item then return end

		
		if item == workspace or item:IsA("Terrain") then
			Main.Notify(item.Name.." can't be previewed: pick a model or a part", "warn")
			return
		end
		ModelViewer.StopViewModel(updating)

		local wasArchivable = item.Archivable
		item.Archivable = true
		local clone = item:Clone()
		item.Archivable = wasArchivable

		
		if clone and not clone:IsA("Model") then
			local holder = Instance.new("Model")
			clone.Parent = holder
			clone = holder
		end
		if not clone or not clone:FindFirstChildWhichIsA("BasePart", true) then
			if clone then clone:Destroy() end
			model = nil
			if not updating then Main.Notify(item.Name.." has no parts to preview", "warn") end
			return
		end
		model = clone
		model.Parent = viewportFrame

		
		
		local boxCFrame, boxSize = model:GetBoundingBox()
		center = boxCFrame.Position
		if not updating then distance = math.max(boxSize.Magnitude, 2) end

		originalModel = item
		
		if ModelViewer.AutoRefresh and not updating and not refreshLoopRunning then
			refreshLoopRunning = true
			local session = Main.Session
			task.spawn(function()
				while model and ModelViewer.AutoRefresh and Main.Session == session do 
					
					if window:IsContentVisible() then ModelViewer.ViewModel(originalModel, true) end
					task.wait(1 / ModelViewer.RefreshRate)
				end
				refreshLoopRunning = false
			end)
		end
		
		if not updating then
			camera = Instance.new("Camera")
			viewportFrame.CurrentCamera = camera

			camera.Parent = viewportFrame
			camera.FieldOfView = 60
			
			window:SetTitle(item.Name.." - 3D Preview")
			pathLabel.Gui.Text = "path: " .. getPath(originalModel)
			window:Show()
			ModelViewer.IsViewing = true
		end
	end

	ModelViewer.Init = function()
		window = Lib.Window.new()
		window:SetTitle("3D Preview")
		window:Resize(350,200)
		window:SetLayoutId("ModelViewer")
		ModelViewer.Window =  window
		
		viewportFrame = Instance.new("ViewportFrame")
		viewportFrame.Parent = window.GuiElems.Content
		viewportFrame.BackgroundTransparency = 1
		viewportFrame.Size = UDim2.new(1,0,1,0)
		
		pathLabel = Lib.Label.new()
		pathLabel.Gui.Parent = window.GuiElems.Content
		pathLabel.Gui.AnchorPoint = Vector2.new(0,1)
		pathLabel.Gui.Text = ""
		pathLabel.Gui.TextSize = 12
		pathLabel.Gui.TextColor3 = Settings.Theme.ReadOnlyText 
		pathLabel.Gui.TextTransparency = 0
		pathLabel.Gui.Position = UDim2.new(0,1,1,0)
		pathLabel.Gui.Size = UDim2.new(1,-1,0,15)
		pathLabel.Gui.BackgroundTransparency = 1
		
		settingsButton = Instance.new("ImageButton",window.GuiElems.Content)
		settingsButton.AnchorPoint = Vector2.new(1,0)
		settingsButton.BackgroundTransparency = 1
		settingsButton.Size = UDim2.new(0,15,0,15)
		settingsButton.Position = UDim2.new(1,-3,0,3)
		settingsButton.Image = "rbxassetid://6578871732"
		settingsButton.ImageTransparency = 0.5
		Lib.Tooltip.attach(settingsButton, "Viewer options")
		settingsButton.Visible = env.isonmobile 

		local rotationX, rotationY = math.rad(-15), math.pi 
		local dragging = false
		local hovering = false
		local lastpos = Vector2.zero

		viewportFrame.InputBegan:Connect(function(input)
			if not ModelViewer.EnableInputCamera then return end
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				dragging = true
				lastpos = input.Position
			elseif input.KeyCode == Enum.KeyCode.LeftShift then
				ModelViewer.ZoomMultiplier = 10
			end
		end)
		

		viewportFrame.MouseEnter:Connect(function()
			hovering = true
		end)
		viewportFrame.MouseLeave:Connect(function()
			hovering = false
		end)

		viewportFrame.InputEnded:Connect(function(input)
			if not ModelViewer.EnableInputCamera then return end
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				dragging = false
			elseif input.KeyCode == Enum.KeyCode.LeftShift then
				ModelViewer.ZoomMultiplier = 2
			end
		end)

		viewportFrame.InputChanged:Connect(function(input)
			if not ModelViewer.EnableInputCamera then return end
			if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
				local delta = input.Position - lastpos
				lastpos = input.Position

				rotationY -= delta.X * 0.01
				rotationX -= delta.Y * 0.01
				rotationX = math.clamp(rotationX, -math.pi/2 + 0.1, math.pi/2 - 0.1)
			end

			if input.UserInputType == Enum.UserInputType.MouseWheel and hovering then
				
				distance = math.clamp(distance * (1 - input.Position.Z * 0.05 * ModelViewer.ZoomMultiplier), 0.1, math.huge)
			end
		end)

		Main.Track(RunService.RenderStepped:Connect(function(dt)
			if camera and model then
				if not dragging and ModelViewer.AutoRotate then
					rotationY += ModelViewer.RotationSpeed * dt * 60
				end

				local offset = CFrame.new(0, 0, distance)
				local rotation = CFrame.Angles(0, rotationY, 0) * CFrame.Angles(rotationX, 0, 0)

				local camCF = CFrame.new(center) * rotation * offset

				camera.CFrame = CFrame.lookAt(camCF.Position, center)

			end
		end))

		
		local context = Lib.ContextMenu.new()
		
		local absoluteSize = context.Gui.AbsoluteSize
		context.MaxHeight = (absoluteSize.Y <= 600 and (absoluteSize.Y - 40)) or nil

		
		context:Register("STOP",{Name = "Stop Viewing", OnClick = function()
			ModelViewer.StopViewModel()
		end})
		context:Register("EXIT",{Name = "Exit", OnClick = function()
			ModelViewer.StopViewModel()
			context:Hide()
			window:Hide()
		end})
		context:Register("COPY_PATH",{Name = "Copy Path", OnClick = function()
			if model and env.setclipboard then
				env.setclipboard(getPath(originalModel))
			end
		end})
		context:Register("REFRESH",{Name = "Refresh", OnClick = function()
			if originalModel then
				ModelViewer.ViewModel(originalModel)
			end
		end})
		context:Register("ENABLE_AUTO_REFRESH",{Name = "Enable Auto Refresh", OnClick = function()
			if originalModel then
				ModelViewer.AutoRefresh = true
				ModelViewer.ViewModel(originalModel)
			end
		end})
		context:Register("DISABLE_AUTO_REFRESH",{Name = "Disable Auto Refresh", OnClick = function()
			if originalModel then
				ModelViewer.AutoRefresh = false
				ModelViewer.ViewModel(originalModel)
			end
		end})
		context:Register("SAVE_INST",{Name = "Save to File", OnClick = function()
			if model then Lib.SaveObjectPrompt(originalModel) end
		end})
		
		context:Register("ENABLE_AUTO_ROTATE",{Name = "Enable Auto Rotate", OnClick = function()
			ModelViewer.AutoRotate = true
			
		end})
		context:Register("DISABLE_AUTO_ROTATE",{Name = "Disable Auto Rotate", OnClick = function()
			ModelViewer.AutoRotate = false
		end})
		context:Register("LOCK_CAM",{Name = "Lock Camera", OnClick = function()
			ModelViewer.EnableInputCamera = false
		end})
		context:Register("UNLOCK_CAM",{Name = "Unlock Camera", OnClick = function()
			ModelViewer.EnableInputCamera = true
		end})
		
		context:Register("ZOOM_IN",{Name = "Zoom In", OnClick = function()
			distance = math.max(distance * 0.8, 0.1)
		end})

		context:Register("ZOOM_OUT",{Name = "Zoom Out", OnClick = function()
			distance = distance * 1.25
		end})
		
		local function ShowContext()
			context:Clear()

			context:AddRegistered("STOP", not ModelViewer.IsViewing)	
			context:AddRegistered("REFRESH", not ModelViewer.IsViewing)
			context:AddRegistered("COPY_PATH", not ModelViewer.IsViewing or not env.setclipboard)
			context:AddRegistered("SAVE_INST", not ModelViewer.IsViewing)
			context:AddDivider()
			
			if env.isonmobile then
				context:AddRegistered("ZOOM_IN")
				context:AddRegistered("ZOOM_OUT")
				context:AddDivider()
			end

			if ModelViewer.AutoRotate then
				context:AddRegistered("DISABLE_AUTO_ROTATE")
			else
				context:AddRegistered("ENABLE_AUTO_ROTATE")
			end
			if ModelViewer.AutoRefresh then
				context:AddRegistered("DISABLE_AUTO_REFRESH")
			else
				context:AddRegistered("ENABLE_AUTO_REFRESH")
			end
			if ModelViewer.EnableInputCamera then
				context:AddRegistered("LOCK_CAM")
			else
				context:AddRegistered("UNLOCK_CAM")
			end

			context:AddDivider()

			context:AddRegistered("EXIT")

			context:Show()
		end
		
		local function HideContext()
			context:Hide()
		end
		
		viewportFrame.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton2 then
				ShowContext()
			elseif input.UserInputType == Enum.UserInputType.MouseButton1 and Lib.CheckMouseInGui(context.Gui) then
				HideContext()
			end
		end)
		settingsButton.MouseButton1Click:Connect(function()
			ShowContext()
		end)
	end

	return ModelViewer
end

return {InitDeps = initDeps, InitAfterMain = initAfterMain, Main = main}

end,
["Properties"] = function()



local Main,Lib,Apps,Settings 
local Explorer 
local API,RMD,env,service,create 

local function initDeps(data)
	Main = data.Main
	Lib = data.Lib
	Apps = data.Apps
	Settings = data.Settings

	API = data.API
	RMD = data.RMD
	env = data.env
	service = data.service
	create = data.create
end

local function initAfterMain()
	Explorer = Apps.Explorer
end

local function main()
	local Properties = {}

	local window, toolBar, propsFrame
	local scrollV, scrollH
	local categoryOrder
	local props,viewList,expanded,indexableProps,propEntries,autoUpdateObjs = {},{},{},{},{},{}
	local inputBox,inputTextBox,inputProp
	local checkboxes,propCons = {},{}
	local table,string = table,string
	local getPropChangedSignal = game.GetPropertyChangedSignal
	local getAttributeChangedSignal = game.GetAttributeChangedSignal
	local isa = game.IsA
	local getAttribute = game.GetAttribute
	local setAttribute = game.SetAttribute

	Properties.GuiElems = {}
	Properties.Index = 0
	Properties.ViewWidth = 0
	Properties.MinInputWidth = 100
	Properties.EntryIndent = 16
	Properties.EntryOffset = 4
	Properties.NameWidthCache = {}
	Properties.ClassLists = {}
	Properties.SearchText = ""

	Properties.AddAttributeProp = {Category = "Attributes", Class = "", Name = "", SpecialRow = "AddAttribute", Tags = {}}
	Properties.SoundPreviewProp = {Category = "Data", ValueType = {Name = "SoundPlayer"}, Class = "Sound", Name = "Preview", Tags = {}}

	Properties.IgnoreProps = {
		["DataModel"] = {
			["PrivateServerId"] = true,
			["PrivateServerOwnerId"] = true,
			["VIPServerId"] = true,
			["VIPServerOwnerId"] = true
		}
	}

	Properties.ExpandableTypes = {
		["Vector2"] = true,
		["Vector3"] = true,
		["UDim"] = true,
		["UDim2"] = true,
		["CFrame"] = true,
		["Rect"] = true,
		["PhysicalProperties"] = true,
		["Ray"] = true,
		["NumberRange"] = true,
		["Faces"] = true,
		["Axes"] = true,
	}

	Properties.ExpandableProps = {
		["Sound.SoundId"] = true
	}

	Properties.CollapsedCategories = {
		["Surface Inputs"] = true,
		["Surface"] = true
	}

	
	Properties.CompoundParts = {
		Vector2 = {{".X","float"},{".Y","float"}},
		Vector3 = {{".X","float"},{".Y","float"},{".Z","float"}},
		CFrame = {{".Position","Vector3"},{".RightVector","Vector3"},{".UpVector","Vector3"},{".LookVector","Vector3"}},
		UDim = {{".Scale","float"},{".Offset","int"}},
		UDim2 = {{".X","UDim"},{".Y","UDim"}},
		Rect = {{".Min.X","float","X0"},{".Min.Y","float","Y0"},{".Max.X","float","X1"},{".Max.Y","float","Y1"}},
		PhysicalProperties = {{".Density","float"},{".Elasticity","float"},{".ElasticityWeight","float"},{".Friction","float"},{".FrictionWeight","float"}},
		Ray = {{".Origin","Vector3"},{".Direction","Vector3"}},
		NumberRange = {{".Min","float"},{".Max","float"}},
		Faces = {{".Back","bool"},{".Bottom","bool"},{".Front","bool"},{".Left","bool"},{".Right","bool"},{".Top","bool"}},
		Axes = {{".X","bool"},{".Y","bool"},{".Z","bool"}},
	}

	
	Properties.ConflictSubProps = {}
	do
		local function addPaths(list,parts,prefix)
			for _,part in ipairs(parts) do
				local path = prefix..part[1]:sub(2)
				list[#list+1] = path
				local nested = Properties.CompoundParts[part[2]]
				if nested then addPaths(list,nested,path..".") end
			end
		end
		for typeName,parts in pairs(Properties.CompoundParts) do
			Properties.ConflictSubProps[typeName] = {}
			addPaths(Properties.ConflictSubProps[typeName],parts,"")
		end
	end

	Properties.ConflictIgnore = {
		["BasePart"] = {
			["ResizableFaces"] = true
		}
	}

	Properties.RoundableTypes = {
		["float"] = true,
		["double"] = true,
		["Color3"] = true,
		["UDim"] = true,
		["UDim2"] = true,
		["Vector2"] = true,
		["Vector3"] = true,
		["NumberRange"] = true,
		["Rect"] = true,
		["NumberSequence"] = true,
		["ColorSequence"] = true,
		["Ray"] = true,
		["CFrame"] = true
	}

	Properties.TypeNameConvert = {
		["number"] = "double",
		["boolean"] = "bool"
	}

	Properties.ToNumberTypes = {
		["int"] = true,
		["int64"] = true,
		["float"] = true,
		["double"] = true
	}

	Properties.DefaultPropValue = {
		string = "",
		bool = false,
		double = 0,
		UDim = UDim.new(0,0),
		UDim2 = UDim2.new(0,0,0,0),
		BrickColor = BrickColor.new("Medium stone grey"),
		Color3 = Color3.new(1,1,1),
		Vector2 = Vector2.new(0,0),
		Vector3 = Vector3.new(0,0,0),
		NumberSequence = NumberSequence.new(1),
		ColorSequence = ColorSequence.new(Color3.new(1,1,1)),
		NumberRange = NumberRange.new(0),
		Rect = Rect.new(0,0,0,0)
	}

	Properties.AllowedAttributeTypes = {"string","boolean","number","UDim","UDim2","BrickColor","Color3","Vector2","Vector3","NumberSequence","ColorSequence","NumberRange","Rect"}

	Properties.StringToValue = function(prop,str)
		local typeData = prop.ValueType
		local typeName = typeData.Name

		if typeName == "string" or typeName == "ContentId" then
			return str
		elseif typeName == "Content" then
			return Content.fromUri(str)
		elseif Properties.ToNumberTypes[typeName] then
			return tonumber(str)
		elseif typeName == "Vector2" then
			local vals = str:split(",")
			local x,y = tonumber(vals[1]),tonumber(vals[2])
			if x and y and #vals >= 2 then return Vector2.new(x,y) end
		elseif typeName == "Vector3" then
			local vals = str:split(",")
			local x,y,z = tonumber(vals[1]),tonumber(vals[2]),tonumber(vals[3])
			if x and y and z and #vals >= 3 then return Vector3.new(x,y,z) end
		elseif typeName == "UDim" then
			local vals = str:split(",")
			local scale,offset = tonumber(vals[1]),tonumber(vals[2])
			if scale and offset and #vals >= 2 then return UDim.new(scale,offset) end
		elseif typeName == "UDim2" then
			local vals = str:gsub("[{}]",""):split(",")
			local xScale,xOffset,yScale,yOffset = tonumber(vals[1]),tonumber(vals[2]),tonumber(vals[3]),tonumber(vals[4])
			if xScale and xOffset and yScale and yOffset and #vals >= 4 then return UDim2.new(xScale,xOffset,yScale,yOffset) end
		elseif typeName == "CFrame" then
			local vals = str:split(",")
			local s,result = pcall(CFrame.new,unpack(vals))
			if s and #vals >= 12 then return result end
		elseif typeName == "Rect" then
			local vals = str:split(",")
			local s,result = pcall(Rect.new,unpack(vals))
			if s and #vals >= 4 then return result end
		elseif typeName == "Ray" then
			local vals = str:gsub("[{}]",""):split(",")
			local s,origin = pcall(Vector3.new,unpack(vals,1,3))
			local s2,direction = pcall(Vector3.new,unpack(vals,4,6))
			if s and s2 and #vals >= 6 then return Ray.new(origin,direction) end
		elseif typeName == "NumberRange" then
			local vals = str:split(",")
			local s,result = pcall(NumberRange.new,unpack(vals))
			if s and #vals >= 1 then return result end
		elseif typeName == "Color3" then
			local vals = str:gsub("[{}]",""):split(",")
			local s,result = pcall(Color3.fromRGB,unpack(vals))
			if s and #vals >= 3 then return result end
		end

		return nil
	end

	Properties.ValueToString = function(prop,val)
		local typeData = prop.ValueType
		local typeName = typeData.Name

		if typeName == "Color3" then
			return Lib.ColorToBytes(val)
		elseif typeName == "NumberRange" then
			return val.Min..", "..val.Max
		end

		return tostring(val)
	end

	Properties.GetIndexableProps = function(obj,classData)
		if not Main.Elevated then
			if not pcall(function() return obj.ClassName end) then return nil end
		end

		local ignoreProps = Properties.IgnoreProps[classData.Name] or {}

		local result = {}
		local count = 1
		local props = classData.Properties
		for i = 1,#props do
			local prop = props[i]
			if not ignoreProps[prop.Name] then
				local s = pcall(function() return obj[prop.Name] end)
				if s then
					result[count] = prop
					count = count + 1
				end
			end
		end

		return result
	end

	Properties.FindFirstObjWhichIsA = function(class)
		local classList = Properties.ClassLists[class] or {}
		if classList and #classList > 0 then
			return classList[1]
		end

		return nil
	end

	Properties.ComputeConflicts = function(p)
		local maxConflictCheck = Settings.Properties.MaxConflictCheck
		local sList = Explorer.Selection.List
		local classLists = Properties.ClassLists
		local stringSplit = string.split
		local t_clear = table.clear
		local conflictIgnore = Properties.ConflictIgnore
		local conflictMap = {}
		local propList = p and {p} or props

		if p then
			local gName = p.Class.."."..p.Name
			autoUpdateObjs[gName] = nil
			local subProps = Properties.ConflictSubProps[p.ValueType.Name] or {}
			for i = 1,#subProps do
				autoUpdateObjs[gName.."."..subProps[i]] = nil
			end
		else
			table.clear(autoUpdateObjs)
		end

		if #sList > 0 then
			for i = 1,#propList do
				local prop = propList[i]
				local propName,propClass = prop.Name,prop.Class
				local typeData = prop.RootType or prop.ValueType
				local typeName = typeData.Name
				local attributeName = prop.AttributeName
				local gName = propClass.."."..propName

				local checked = 0
				local subProps = Properties.ConflictSubProps[typeName] or {}
				local subPropCount = #subProps
				local toCheck = subPropCount + 1
				local conflictsFound = 0
				local indexNames = {}
				local ignored = conflictIgnore[propClass] and conflictIgnore[propClass][propName]
				local truthyCheck = (typeName == "PhysicalProperties")
				local isAttribute = prop.IsAttribute
				local isMultiType = prop.MultiType

				t_clear(conflictMap)

				if not isMultiType then
					local firstVal,firstObj,firstSet
					local classList = classLists[prop.Class] or {}
					for c = 1,#classList do
						local obj = classList[c]
						if not firstSet then
							if isAttribute then
								firstVal = getAttribute(obj,attributeName)
								if firstVal ~= nil then
									firstObj = obj
									firstSet = true
								end
							else
								firstVal = obj[propName]
								firstObj = obj
								firstSet = true
							end
							if ignored then break end
						else
							local propVal,skip
							if isAttribute then
								propVal = getAttribute(obj,attributeName)
								if propVal == nil then skip = true end
							else
								propVal = obj[propName]
							end

							if not skip then
								if not conflictMap[1] then
									if truthyCheck then
										if (firstVal and true or false) ~= (propVal and true or false) then
											conflictMap[1] = true
											conflictsFound = conflictsFound + 1
										end
									elseif firstVal ~= propVal then
										conflictMap[1] = true
										conflictsFound = conflictsFound + 1
									end
								end

								if subPropCount > 0 then
									for sPropInd = 1,subPropCount do
										local indexes = indexNames[sPropInd]
										if not indexes then indexes = stringSplit(subProps[sPropInd],".") indexNames[sPropInd] = indexes end

										local firstValSub = firstVal
										local propValSub = propVal

										for j = 1,#indexes do
											if not firstValSub or not propValSub then break end 
											local indexName = indexes[j]
											firstValSub = firstValSub[indexName]
											propValSub = propValSub[indexName]
										end

										local mapInd = sPropInd + 1
										if not conflictMap[mapInd] and firstValSub ~= propValSub then
											conflictMap[mapInd] = true
											conflictsFound = conflictsFound + 1
										end
									end
								end

								if conflictsFound == toCheck then break end
							end
						end

						checked = checked + 1
						if checked == maxConflictCheck then break end
					end

					if not conflictMap[1] then autoUpdateObjs[gName] = firstObj end
					for sPropInd = 1,subPropCount do
						if not conflictMap[sPropInd+1] then
							autoUpdateObjs[gName.."."..subProps[sPropInd]] = firstObj
						end
					end
				end
			end
		end

		if p then
			Properties.Refresh()
		end
	end

	
	Properties.ShowExplorerProps = function()
		
		
		if window and not window:IsContentVisible() then
			Properties.Stale = true
			return
		end
		Properties.Stale = false

		local sList = Explorer.Selection.List
		local foundClasses = {}
		local propCount = 1
		local showDeprecated,showHidden = Settings.Properties.ShowDeprecated,Settings.Properties.ShowHidden
		local Classes = API.Classes
		local classLists = {}
		local lower = string.lower
		local RMDCustomOrders = RMD.PropertyOrders
		local getAttributes = game.GetAttributes
		local maxAttrs = Settings.Properties.MaxAttributes
		local showingAttrs = Settings.Properties.ShowAttributes
		local foundAttrs = {}
		local attrCount = 0
		local typeof = typeof
		local typeNameConvert = Properties.TypeNameConvert

		table.clear(props)

		for i = 1,#sList do
			local node = sList[i]
			local obj = node.Obj
			local class = node.Class
			if not class then class = obj.ClassName node.Class = class end

			local apiClass = Classes[class]
			while apiClass do
				local APIClassName = apiClass.Name
				if not foundClasses[APIClassName] then
					local apiProps = indexableProps[APIClassName]
					if not apiProps then apiProps = Properties.GetIndexableProps(obj,apiClass) indexableProps[APIClassName] = apiProps end

					for i = 1,#apiProps do
						local prop = apiProps[i]
						local tags = prop.Tags
						if (not tags.Deprecated or showDeprecated) and (not tags.Hidden or showHidden) then
							props[propCount] = prop
							propCount = propCount + 1
						end
					end
					foundClasses[APIClassName] = true
				end

				local classList = classLists[APIClassName]
				if not classList then classList = {} classLists[APIClassName] = classList end
				classList[#classList+1] = obj

				apiClass = apiClass.Superclass
			end

			if showingAttrs and attrCount < maxAttrs then
				local attrs = getAttributes(obj)
				for name,val in pairs(attrs) do
					local typ = typeof(val)
					if not foundAttrs[name] then
						local category = (typ == "Instance" and "Class") or (typ == "EnumItem" and "Enum") or "Other"
						local valType = {Name = typeNameConvert[typ] or typ, Category = category}
						local attrProp = {IsAttribute = true, Name = "ATTR_"..name, AttributeName = name, DisplayName = name, Class = "Instance", ValueType = valType, Category = "Attributes", Tags = {}}
						props[propCount] = attrProp
						propCount = propCount + 1
						attrCount = attrCount + 1
						foundAttrs[name] = {typ,attrProp}
						if attrCount == maxAttrs then break end
					elseif foundAttrs[name][1] ~= typ then
						foundAttrs[name][2].MultiType = true
						foundAttrs[name][2].Tags.ReadOnly = true
						foundAttrs[name][2].ValueType = {Name = "string"}
					end
				end
			end
		end

		table.sort(props,function(a,b)
			if a.Category ~= b.Category then
				return (categoryOrder[a.Category] or 9999) < (categoryOrder[b.Category] or 9999)
			else
				local aOrder = (RMDCustomOrders[a.Class] and RMDCustomOrders[a.Class][a.Name]) or 9999999
				local bOrder = (RMDCustomOrders[b.Class] and RMDCustomOrders[b.Class][b.Name]) or 9999999
				if aOrder ~= bOrder then
					return aOrder < bOrder
				else
					return lower(a.Name) < lower(b.Name)
				end
			end
		end)

		
		Properties.ClassLists = classLists
		Properties.ComputeConflicts()
		if #props > 0 then
			props[#props+1] = Properties.AddAttributeProp
		end

		Properties.Update()
		Properties.Refresh()
	end

	Properties.UpdateView = function()
		local maxEntries = math.ceil(propsFrame.AbsoluteSize.Y / 23)
		local maxX = propsFrame.AbsoluteSize.X
		local totalWidth = Properties.ViewWidth + Properties.MinInputWidth

		scrollV.VisibleSpace = maxEntries
		scrollV.TotalSpace = #viewList + 1
		scrollH.VisibleSpace = maxX
		scrollH.TotalSpace = totalWidth

		scrollV.Gui.Visible = #viewList + 1 > maxEntries
		scrollH.Gui.Visible = Settings.Properties.ScaleType == 0 and totalWidth > maxX

		local oldSize = propsFrame.Size
		propsFrame.Size = UDim2.new(1,(scrollV.Gui.Visible and -16 or 0),1,(scrollH.Gui.Visible and -39 or -23))
		if oldSize ~= propsFrame.Size then
			Properties.UpdateView()
		else
			scrollV:Update()
			scrollH:Update()

			if scrollV.Gui.Visible and scrollH.Gui.Visible then
				scrollV.Gui.Size = UDim2.new(0,16,1,-39)
				scrollH.Gui.Size = UDim2.new(1,-16,0,16)
				Properties.Window.GuiElems.Content.ScrollCorner.Visible = true
			else
				scrollV.Gui.Size = UDim2.new(0,16,1,-23)
				scrollH.Gui.Size = UDim2.new(1,0,0,16)
				Properties.Window.GuiElems.Content.ScrollCorner.Visible = false
			end

			Properties.Index = scrollV.Index
		end
	end

	
	local function propFullName(prop)
		return prop.Class.."."..prop.Name..(prop.SubName or "")
	end

	local function propEntryKey(prop)
		return prop.CategoryName and "CAT_"..prop.CategoryName or propFullName(prop)
	end

	Properties.MakeSubProp = function(prop,subName,valueType,displayName)
		local subProp = {}
		for i,v in pairs(prop) do
			subProp[i] = v
		end
		subProp.RootType = subProp.RootType or subProp.ValueType
		subProp.ValueType = valueType
		subProp.SubName = subProp.SubName and (subProp.SubName..subName) or subName
		subProp.DisplayName = displayName

		return subProp
	end

	Properties.GetExpandedProps = function(prop)
		local result = {}
		for i,part in ipairs(Properties.CompoundParts[prop.ValueType.Name] or {}) do
			result[i] = Properties.MakeSubProp(prop,part[1],{Name = part[2]},part[3])
		end

		if prop.Name == "SoundId" and prop.Class == "Sound" then
			result[1] = Properties.SoundPreviewProp
		end

		return result
	end

	Properties.Update = function()
		table.clear(viewList)

		local nameWidthCache = Properties.NameWidthCache
		local lastCategory
		local count = 1
		local maxWidth,maxDepth = 0,1

		local textServ = service.TextService
		local getTextSize = textServ.GetTextSize
		local font = Enum.Font.SourceSans
		local size = Vector2.new(math.huge,20)
		local stringSplit = string.split
		local entryIndent = Properties.EntryIndent
		local isFirstScaleType = Settings.Properties.ScaleType == 0
		local find,lower = string.find,string.lower
		local searchText = (#Properties.SearchText > 0 and lower(Properties.SearchText))

		local function recur(props,depth)
			for i = 1,#props do
				local prop = props[i]
				local propName = prop.Name
				local subName = prop.SubName
				local category = prop.Category

				local visible
				if searchText and depth == 1 then
					if find(lower(propName),searchText,1,true) then
						visible = true
					end
				else
					visible = true
				end

				if visible and lastCategory ~= category then
					viewList[count] = {CategoryName = category}
					count = count + 1
					lastCategory = category
				end

				if (expanded["CAT_"..category] and visible) or prop.SpecialRow then
					if depth > 1 then prop.Depth = depth if depth > maxDepth then maxDepth = depth end end

					if isFirstScaleType then
						local nameArr = subName and stringSplit(subName,".")
						local displayName = prop.DisplayName or (nameArr and nameArr[#nameArr]) or propName

						local nameWidth = nameWidthCache[displayName]
						if not nameWidth then nameWidth = getTextSize(textServ,displayName,14,font,size).X nameWidthCache[displayName] = nameWidth end

						local totalWidth = nameWidth + entryIndent*depth
						if totalWidth > maxWidth then
							maxWidth = totalWidth
						end
					end

					viewList[count] = prop
					count = count + 1

					local fullName = propFullName(prop)
					if expanded[fullName] then
						local nextDepth = depth+1
						local expandedProps = Properties.GetExpandedProps(prop)
						if #expandedProps > 0 then
							recur(expandedProps,nextDepth)
						end
					end
				end
			end
		end
		recur(props,1)

		inputProp = nil
		Properties.ViewWidth = maxWidth + 9 + Properties.EntryOffset
		Properties.UpdateView()
	end

	Properties.NewPropEntry = function(index)
		local newEntry = Properties.EntryTemplate:Clone()
		local nameFrame = newEntry.NameFrame
		local valueFrame = newEntry.ValueFrame
		local function rowProp() 
			return viewList[index + Properties.Index]
		end
		local newCheckbox = Lib.Checkbox.new(1)
		newCheckbox.Gui.Position = UDim2.new(0,3,0,3)
		newCheckbox.Gui.Parent = valueFrame
		newCheckbox.OnInput:Connect(function()
			local prop = rowProp()
			if not prop then return end

			if prop.ValueType.Name == "PhysicalProperties" then
				Properties.SetProp(prop,newCheckbox.Toggled and true or nil)
			else
				Properties.SetProp(prop,newCheckbox.Toggled)
			end
		end)
		checkboxes[index] = newCheckbox

		local iconFrame = Main.MiscIcons:GetLabel()
		iconFrame.Position = UDim2.new(0,2,0,3)
		iconFrame.Parent = newEntry.ValueFrame.RightButton

		
		Lib.Tooltip.attach(valueFrame.RightButton,function()
			local prop = rowProp()
			if not prop then return end
			local typeName = prop.ValueType and prop.ValueType.Name
			return (typeName == "NumberSequence" or typeName == "ColorSequence") and "Edit the sequence" or "Clear this reference"
		end)
		Lib.Tooltip.attach(valueFrame.ColorButton,"Pick a colour")
		Lib.Tooltip.attach(newEntry.EditAttributeButton,"Edit or delete this attribute")
		Lib.Tooltip.attach(nameFrame.ToggleAttributes,"Show or hide the attributes of the selected objects")
		Lib.Tooltip.attach(valueFrame.ValueBox,function()
			local prop = rowProp()
			if prop and prop.Tags and prop.Tags.ReadOnly then return "Read-only: this property can't be changed" end
		end)

		newEntry.Position = UDim2.new(0,0,0,23*(index-1))

		nameFrame.Expand.InputBegan:Connect(function(input)
			local prop = rowProp()
			if not prop or input.UserInputType ~= Enum.UserInputType.MouseMovement then return end

			local fullName = propEntryKey(prop)

			Main.MiscIcons:DisplayByKey(newEntry.NameFrame.Expand.Icon, expanded[fullName] and "Collapse_Over" or "Expand_Over")
		end)

		nameFrame.Expand.InputEnded:Connect(function(input)
			local prop = rowProp()
			if not prop or input.UserInputType ~= Enum.UserInputType.MouseMovement then return end

			local fullName = propEntryKey(prop)

			Main.MiscIcons:DisplayByKey(newEntry.NameFrame.Expand.Icon, expanded[fullName] and "Collapse" or "Expand")
		end)

		nameFrame.Expand.MouseButton1Down:Connect(function()
			local prop = rowProp()
			if not prop then return end

			local fullName = propEntryKey(prop)
			if not prop.CategoryName and not Properties.ExpandableTypes[prop.ValueType and prop.ValueType.Name] and not Properties.ExpandableProps[fullName] then return end

			expanded[fullName] = not expanded[fullName]
			Properties.Update()
			Properties.Refresh()
		end)

		nameFrame.PropName.InputBegan:Connect(function(input)
			local prop = rowProp()
			if not prop then return end
			if input.UserInputType == Enum.UserInputType.MouseMovement and not nameFrame.PropName.TextFits then
				local fullNameFrame = Properties.FullNameFrame	
				local nameArr = string.split(propFullName(prop),".")
				local dispName = prop.DisplayName or nameArr[#nameArr]
				local sizeX = service.TextService:GetTextSize(dispName,14,Enum.Font.SourceSans,Vector2.new(math.huge,20)).X

				fullNameFrame.TextLabel.Text = dispName
				fullNameFrame.Size = UDim2.new(0,sizeX + 4,0,22)
				fullNameFrame.Visible = true
				Properties.FullNameFrameIndex = index
				Properties.FullNameFrameAttach.SetData(fullNameFrame, {Target = nameFrame})
				Properties.FullNameFrameAttach.Enable()
			end
		end)

		nameFrame.PropName.InputEnded:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseMovement and Properties.FullNameFrameIndex == index then
				Properties.FullNameFrame.Visible = false
				Properties.FullNameFrameAttach.Disable()
			end
		end)

		valueFrame.ValueBox.MouseButton1Down:Connect(function()
			local prop = rowProp()
			if not prop then return end

			Properties.SetInputProp(prop,index)
		end)

		valueFrame.ColorButton.MouseButton1Down:Connect(function()
			local prop = rowProp()
			if not prop then return end

			Properties.SetInputProp(prop,index,"color")
		end)

		valueFrame.RightButton.MouseButton1Click:Connect(function()
			local prop = rowProp()
			if not prop then return end

			local fullName = propFullName(prop)
			local inputFullName = inputProp and propFullName(inputProp)

			if fullName == inputFullName and inputProp.ValueType.Category == "Class" then
				inputProp = nil
				Properties.SetProp(prop,nil)
			else
				Properties.SetInputProp(prop,index,"right")
			end
		end)

		nameFrame.ToggleAttributes.MouseButton1Click:Connect(function()
			Settings.Properties.ShowAttributes = not Settings.Properties.ShowAttributes
			Properties.ShowExplorerProps()
		end)

		newEntry.RowButton.MouseButton1Click:Connect(function()
			Properties.DisplayAddAttributeWindow()
		end)

		
		local function rowMenu()
			local prop = rowProp()
			if prop and not prop.CategoryName and not prop.SpecialRow then Properties.DisplayPropContext(prop) end
		end
		newEntry.MouseButton2Click:Connect(rowMenu)
		valueFrame.ValueBox.MouseButton2Click:Connect(rowMenu)

		newEntry.EditAttributeButton.MouseButton1Down:Connect(function()
			local prop = rowProp()
			if not prop then return end

			Properties.DisplayAttributeContext(prop)
		end)

		valueFrame.SoundPreview.ControlButton.MouseButton1Click:Connect(function()
			if Properties.PreviewSound and Properties.PreviewSound.Playing then
				Properties.SetSoundPreview(false)
			else
				local soundObj = Properties.FindFirstObjWhichIsA("Sound")
				if soundObj then Properties.SetSoundPreview(soundObj) end
			end
		end)

		valueFrame.SoundPreview.InputBegan:Connect(function(input)
			if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end

			local releaseEvent,mouseEvent
			releaseEvent = service.UserInputService.InputEnded:Connect(function(input)
				if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
				releaseEvent:Disconnect()
				mouseEvent:Disconnect()
			end)

			local timeLine = newEntry.ValueFrame.SoundPreview.TimeLine
			local soundObj = Properties.FindFirstObjWhichIsA("Sound")
			if soundObj then Properties.SetSoundPreview(soundObj,true) end

			local function update(input)
				local sound = Properties.PreviewSound
				if not sound or sound.TimeLength == 0 then return end

				local mouseX = input.Position.X
				local timeLineSize = timeLine.AbsoluteSize
				local relaX = mouseX - timeLine.AbsolutePosition.X

				if timeLineSize.X <= 1 then return end
				if relaX < 0 then relaX = 0 elseif relaX >= timeLineSize.X then relaX = timeLineSize.X-1 end

				local perc = (relaX/(timeLineSize.X-1))
				sound.TimePosition = perc*sound.TimeLength
				timeLine.Slider.Position = UDim2.new(perc,-4,0,-8)
			end
			update(input)

			mouseEvent = service.UserInputService.InputChanged:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseMovement then
					update(input)
				end
			end)
		end)

		newEntry.Parent = propsFrame

		return {
			Gui = newEntry,
			GuiElems = {
				NameFrame = nameFrame,
				ValueFrame = valueFrame,
				PropName = nameFrame.PropName,
				ValueBox = valueFrame.ValueBox,
				Expand = nameFrame.Expand,
				ColorButton = valueFrame.ColorButton,
				ColorPreview = valueFrame.ColorButton.ColorPreview,
				Gradient = valueFrame.ColorButton.ColorPreview.UIGradient,
				EnumArrow = valueFrame.EnumArrow,
				Checkbox = valueFrame.Checkbox,
				RightButton = valueFrame.RightButton,
				RightButtonIcon = iconFrame,
				RowButton = newEntry.RowButton,
				EditAttributeButton = newEntry.EditAttributeButton,
				ToggleAttributes = nameFrame.ToggleAttributes,
				SoundPreview = valueFrame.SoundPreview,
				SoundPreviewSlider = valueFrame.SoundPreview.TimeLine.Slider
			}
		}
	end

	Properties.GetSoundPreviewEntry = function()
		for i = 1,#viewList do
			if viewList[i] == Properties.SoundPreviewProp then
				return propEntries[i - Properties.Index]
			end
		end
	end

	Properties.SetSoundPreview = function(soundObj,noplay)
		local sound = Properties.PreviewSound
		if not sound then
			sound = Instance.new("Sound")
			sound.Name = "Preview"
			sound.Paused:Connect(function()
				local entry = Properties.GetSoundPreviewEntry()
				if entry then Main.MiscIcons:DisplayByKey(entry.GuiElems.SoundPreview.ControlButton.Icon, "Play") end
			end)
			sound.Resumed:Connect(function() Properties.Refresh() end)
			sound.Ended:Connect(function()
				local entry = Properties.GetSoundPreviewEntry()
				if entry then entry.GuiElems.SoundPreviewSlider.Position = UDim2.new(0,-4,0,-8) end
				Properties.Refresh()
			end)
			sound.Parent = window.Gui
			Properties.PreviewSound = sound
		end

		if not soundObj then
			sound:Pause()
		else
			local newId = sound.SoundId ~= soundObj.SoundId
			sound.SoundId = soundObj.SoundId
			sound.PlaybackSpeed = soundObj.PlaybackSpeed
			sound.Volume = soundObj.Volume
			if newId then sound.TimePosition = 0 end
			if not noplay then sound:Resume() end

			coroutine.wrap(function()
				local previewTime = tick()
				Properties.SoundPreviewTime = previewTime
				while previewTime == Properties.SoundPreviewTime and sound.Playing do
					local entry = Properties.GetSoundPreviewEntry()
					if entry then
						local tl = sound.TimeLength
						local perc = sound.TimePosition/(tl == 0 and 1 or tl)
						entry.GuiElems.SoundPreviewSlider.Position = UDim2.new(perc,-4,0,-8)
					end
					Lib.FastWait()
				end
			end)()
			Properties.Refresh()
		end
	end

	
	
	
	Properties.DisplayPropContext = function(prop)
		local context = Properties.PropContext
		if not context then
			context = Lib.ContextMenu.new()
			context.Iconless = true
			context.Width = 190
			Properties.PropContext = context
		end
		context:Clear()

		local obj = Properties.FindFirstObjWhichIsA(prop.Class)
		local value = Properties.GetPropVal(prop,obj)
		local noClipboard = env.setclipboard == nil and "Your executor has no setclipboard" or nil
		local function copy(text)
			env.setclipboard(text)
			Main.Notify("Copied "..(#text > 60 and (text:sub(1,57).."...") or text),"success")
		end
		local function item(name,reason,onClick)
			context:Add({Name = name, Disabled = reason ~= nil, Reason = reason, OnClick = onClick})
		end

		
		local access = prop.IsAttribute and (':GetAttribute("'..Lib.FormatLuaString(prop.AttributeName)..'")') or ("."..prop.Name)
		access = access..(prop.SubName or "")

		item("Copy Value",noClipboard or (value == nil and "It has no value") or nil,function()
			copy(typeof(value) == "Instance" and value:GetFullName() or Properties.ValueToString(prop,value))
		end)
		item("Copy Value as Code",noClipboard or (value == nil and "It has no value") or nil,function()
			copy((Lib.ToLua(value)))
		end)
		item("Copy Name",noClipboard,function()
			copy(prop.IsAttribute and prop.AttributeName or (prop.Name..(prop.SubName or "")))
		end)
		item("Copy Path",noClipboard or (obj == nil and "Nothing is selected") or nil,function()
			copy(Explorer.GetInstancePath(obj)..access)
		end)
		if typeof(value) == "Instance" then
			context:AddDivider()
			item("Select in Explorer",nil,function() Explorer.SelectObj(value) end)
		end

		context:Show()
	end

	Properties.DisplayAttributeContext = function(prop)
		local context = Properties.AttributeContext
		if not context then
			context = Lib.ContextMenu.new()
			context.Iconless = true
