	local function isSkipped(obj)
		if not obj then
			return true
		end
		local ok, full = pcall(function()
			return obj:GetFullName()
		end)
		if not ok or not full then
			return true
		end
		
		if full:find("^CoreGui") or full:find("^CorePackages") then
			return true
		end
		if full:find("RobloxPluginGuiService") or full:find("PluginGuiService") then
			return true
		end
		if full:find("RobloxReplicatedStorage") then
			return true
		end
		
		if full:find("PlayerScripts%.PlayerModule") or full:find("PlayerScripts%.RbxCharacterSounds") then
			return true
		end
		if full:find("PlayerScripts%.ChatScript") or full:find("%.BubbleChat") then
			return true
		end
		if full:find("StarterPlayer%.StarterPlayerScripts%.PlayerModule") then
			return true
		end
		
		local sn = obj.ClassName
		if obj.Parent == game and SkipServiceNames[obj.Name] == true then
			return true
		end
		
		local cur = obj
		for _ = 1, 32 do
			if not cur then
				break
			end
			if cur.Parent == game and SkipServiceNames[cur.Name] == true then
				return true
			end
			if SkipNameExact[cur.Name] then
				return true
			end
			cur = cur.Parent
		end
		return false
	end

	local function log(msg, color)
		if not logFrame then
			return
		end
		local t = Instance.new("TextLabel")
		t.BackgroundTransparency = 1
		t.Size = UDim2.new(1, -8, 0, 16)
		t.Font = Enum.Font.Code
		t.TextSize = 13
		t.TextXAlignment = Enum.TextXAlignment.Left
		t.TextColor3 = color or Color3.fromRGB(200, 200, 200)
		t.Text = os.date("%H:%M:%S") .. "  " .. tostring(msg)
		t.TextWrapped = true
		t.AutomaticSize = Enum.AutomaticSize.Y
		t.Parent = logFrame
		logFrame.CanvasPosition = Vector2.new(0, 9e9)
	end

	local function setStatus(text, pct)
		if statusLabel then
			statusLabel.Text = text
		end
		if progressBar and pct then
			progressBar.Size = UDim2.new(math.clamp(pct, 0, 1), 0, 1, 0)
		end
	end

	local function addFinding(sev, category, title, path, detail, scriptRef, meta)
		local f = {
			severity = sev or 2,
			category = category or "General",
			title = title or "Finding",
			path = path or "",
			detail = detail or "",
			scriptRef = scriptRef,
			aiNote = nil,
			meta = meta or {},
			testable = false,
		}
		
		if category == "Remote" or category == "Backdoor" or category == "RemoteAbuse" then
			f.testable = true
		end
		if meta and meta.remote then
			f.testable = true
			f.remote = meta.remote
		end
		table.insert(findings, f)
		return f
	end

	
