		{pat = "OnServerInvoke%s*=", sev = 2, cat = "RemoteHandler", title = "OnServerInvoke handler"},
		{pat = "FireAllClients%s*%(", sev = 2, cat = "RemoteCall", title = "FireAllClients"},
