	local function getRequestFn()
		if env and env.request then
			return env.request
		elseif syn and syn.request then
			return syn.request
		elseif http_request then
			return http_request
		elseif request then
			return request
		end
		return nil
	end

	local function aiRequest(prompt)
		local requestFn = getRequestFn()
		if not requestFn then
			return nil, "no request function"
		end
		local HttpService = game:GetService("HttpService")

		local systemPrompt = table.concat({
			"You are an elite Roblox Luau security auditor specialized in backdoors, remote events, FE bypasses, gear/mesh loaders, and server crash vectors.",
			"Analyze the finding with technical precision.",
			"Reply in EXACTLY this format (no markdown):",
			"VERDICT: CONFIRMED|SUSPICIOUS|FALSE_POSITIVE",
			"SEVERITY: 1-5",
			"REASON: <one tight sentence>",
			"EXPLOIT: <how an attacker would abuse it, or NONE>",
			"If evidence is weak, VERDICT must be FALSE_POSITIVE.",
			"Never invent APIs. Never mention CoreGui internals as vulns.",
		}, " ")

		
		local ok, res = pcall(function()
			return requestFn({
				Url = "https://api.llm7.io/v1/chat/completions",
				Method = "POST",
				Headers = {
					["Content-Type"] = "application/json",
					["Authorization"] = "Bearer unused",
				},
				Body = HttpService:JSONEncode({
					model = "gpt-oss:20b",
					messages = {
						{role = "system", content = systemPrompt},
						{role = "user", content = prompt},
					},
					max_tokens = 220,
					temperature = 0.05,
				}),
			})
		end)
		if ok and res and (res.StatusCode == 200 or res.StatusCode == 201) and res.Body then
			local decoded = nil
			pcall(function()
				decoded = HttpService:JSONDecode(res.Body)
			end)
			if decoded and decoded.choices and decoded.choices[1] and decoded.choices[1].message then
				return decoded.choices[1].message.content, "llm7"
			end
		end

		
		ok, res = pcall(function()
			return requestFn({
				Url = "https://api.llm7.io/v1/chat/completions",
				Method = "POST",
				Headers = {
					["Content-Type"] = "application/json",
					["Authorization"] = "Bearer unused",
				},
				Body = HttpService:JSONEncode({
					model = "default",
					messages = {
						{role = "system", content = systemPrompt},
						{role = "user", content = prompt},
					},
					max_tokens = 200,
					temperature = 0.1,
				}),
			})
		end)
		if ok and res and (res.StatusCode == 200 or res.StatusCode == 201) and res.Body then
			local decoded = nil
			pcall(function()
				decoded = HttpService:JSONDecode(res.Body)
			end)
			if decoded and decoded.choices and decoded.choices[1] and decoded.choices[1].message then
				return decoded.choices[1].message.content, "llm7-default"
			end
		end

		
		local full = systemPrompt .. "\n\n" .. prompt
		local encoded = full:gsub("[^%w%-%_%.~]", function(ch)
			return string.format("%%%02X", string.byte(ch))
		end)
		if #encoded > 1800 then
			encoded = string.sub(encoded, 1, 1800)
		end
		ok, res = pcall(function()
			return requestFn({
				Url = "https://text.pollinations.ai/" .. encoded,
				Method = "GET",
			})
		end)
		if ok and res and res.StatusCode == 200 and type(res.Body) == "string" and #res.Body > 8 then
			return res.Body, "pollinations"
		end

		
		ok, res = pcall(function()
			return requestFn({
				Url = "https://text.pollinations.ai/openai",
				Method = "POST",
				Headers = {["Content-Type"] = "application/json"},
				Body = HttpService:JSONEncode({
					model = "openai",
					messages = {
						{role = "system", content = systemPrompt},
						{role = "user", content = prompt},
					},
					max_tokens = 200,
				}),
			})
		end)
		if ok and res and res.StatusCode == 200 and res.Body then
			local decoded = nil
			pcall(function()
				decoded = HttpService:JSONDecode(res.Body)
			end)
			if decoded and decoded.choices and decoded.choices[1] and decoded.choices[1].message then
				return decoded.choices[1].message.content, "pollinations-openai"
			end
			if type(res.Body) == "string" and #res.Body > 8 and not string.find(res.Body, "^{") then
				return res.Body, "pollinations-raw"
			end
		end

		return nil, "all AI endpoints failed"
	end

	local function parseAIVerdict(reply)
		local upper = string.upper(tostring(reply or ""))
		local verdict = "SUSPICIOUS"
		if string.find(upper, "FALSE_POSITIVE") then
			verdict = "FALSE_POSITIVE"
		elseif string.find(upper, "CONFIRMED") then
			verdict = "CONFIRMED"
		end
		local sev = nil
		local sevCap = string.match(reply or "", "[Ss][Ee][Vv][Ee][Rr][Ii][Tt][Yy]%s*:%s*(%d)")
		if sevCap then
			sev = tonumber(sevCap)
		end
		local reason = string.match(reply or "", "[Rr][Ee][Aa][Ss][Oo][Nn]%s*:%s*([^\n]+)")
		local exploit = string.match(reply or "", "[Ee][Xx][Pp][Ll][Oo][Ii][Tt]%s*:%s*([^\n]+)")
		return verdict, sev, reason, exploit
	end

	local function runAIAnalysis()
		setStatus("Deep AI analysis...", 0.9)
		
		local ranked = {}
		for _, f in ipairs(findings) do
			local score = (f.severity or 0) * 10
			if f.category == "BackdoorConfirmed" then
				score = score + 50
			elseif f.category == "Backdoor" or f.category == "BackdoorSuspect" then
				score = score + 30
			elseif f.category == "CrashRisk" or f.category == "AssetLoad" or f.category == "Exfil" then
				score = score + 20
			elseif f.category == "Gear" or f.category == "Mesh" then
				score = score + 10
			end
			table.insert(ranked, {f = f, score = score})
		end
		table.sort(ranked, function(a, b)
			return a.score > b.score
		end)

		local limit = math.min(#ranked, 14)
		log("Deep AI queue: " .. limit .. " findings (multi-endpoint)", Color3.fromRGB(200, 180, 255))
		local confirmed, dismissed = 0, 0

		for i = 1, limit do
			if not scanRunning then
				break
			end
			local f = ranked[i].f
			local snippet = ""
			if f.scriptRef then
				local attr = f.scriptRef:GetAttribute("_DexScanSnippet")
				if type(attr) == "string" then
					snippet = attr
				end
				local liveSrc = safeDecompile(f.scriptRef)
				if type(liveSrc) == "string" and #liveSrc > 0 then
					snippet = liveSrc
				end
			end
			local prompt = string.format(
				"Finding #%d\nSeverity:%s Category:%s Title:%s\nPath:%s\nDetail:%s\nMeta:%s\nCode snippet:\n%s\n\nClassify this Roblox security finding. This is real decompiled script source. Analyze the actual code logic for exploitable/vulnerable behavior, not just names.",
				i,
				tostring(f.severity),
				tostring(f.category),
				tostring(f.title),
				tostring(f.path),
				tostring(f.detail),
				string.sub(snippet, 1, 3000)
			)
			
			if f.meta then
				local bits = {}
				for k, v in pairs(f.meta) do
					table.insert(bits, tostring(k) .. "=" .. tostring(v))
				end
				prompt = prompt .. "\nMetaFields: " .. table.concat(bits, ", ")
			end

			log(string.format("AI [%d/%d] %s", i, limit, f.title), Color3.fromRGB(200, 180, 255))
			local reply, src = aiRequest(prompt)
			if reply then
				local verdict, sev, reason, exploit = parseAIVerdict(reply)
				local clean = string.gsub(reply, "[\r\n]+", " | ")
				if #clean > 220 then
					clean = string.sub(clean, 1, 220) .. "â€¦"
				end
				f.aiNote = clean
				f.aiVerdict = verdict
				f.aiSource = src
				if verdict == "FALSE_POSITIVE" then
					f.severity = math.min(f.severity or 2, 2)
					dismissed = dismissed + 1
					log("AI FALSE_POSITIVE (" .. tostring(src) .. "): " .. f.title, Color3.fromRGB(140, 140, 140))
				elseif verdict == "CONFIRMED" then
					if sev and sev >= (f.severity or 0) then
						f.severity = math.clamp(sev, 1, 5)
					else
						f.severity = math.max(f.severity or 3, 4)
					end
					confirmed = confirmed + 1
					if reason then
						f.detail = (f.detail or "") .. " | AI: " .. reason
					end
					if exploit and not string.find(string.upper(exploit), "NONE") then
						f.detail = f.detail .. " | EXPLOIT: " .. exploit
					end
					log("AI CONFIRMED (" .. tostring(src) .. "): " .. f.title, Color3.fromRGB(255, 120, 120))
				else
					log("AI SUSPICIOUS (" .. tostring(src) .. "): " .. string.sub(clean, 1, 100), Color3.fromRGB(255, 200, 120))
				end
			else
				log("AI skip: " .. tostring(src), Color3.fromRGB(255, 180, 100))
			end
			setStatus(string.format("AI %d/%d (ok:%d fp:%d)", i, limit, confirmed, dismissed), 0.9 + 0.08 * (i / limit))
			task.wait(0.9)
		end
		log(string.format("AI done â€” confirmed=%d dismissed=%d", confirmed, dismissed), Color3.fromRGB(180, 255, 180))
	end

