	local function scanServerBytecode()
		if scanRunning then
			log("Busy â€” stop current scan first", Color3.fromRGB(255, 180, 80))
			return
		end
		scanRunning = true
		local overlay, statusLbl = showBytecodeOverlay(
			"Finding Server Script Bytecode",
			"We will inspect the memory this client can reach and process it with our AI engine to find traces of server script bytecode."
		)
		setStatus("Server bytecode scan...", 0.05)
		log("=== DexHoney: Server bytecode / memory pass ===", Color3.fromRGB(255, 190, 70))
		task.wait(0.4)

		local hits = 0
		local ok, err = pcall(function()
			
			statusLbl.Text = "Reading script bytecode..."
			setStatus("Reading bytecode...", 0.2)
			local roots = collectScanRoots()
			local scripts = {}
			for _, root in ipairs(roots) do
				for _, obj in ipairs(iterDescendantsFiltered(root)) do
					if obj:IsA("LuaSourceContainer") and not isSkipped(obj) then
						table.insert(scripts, obj)
					end
				end
			end
			log("Bytecode targets: " .. #scripts, Color3.fromRGB(200, 180, 120))
			local getbc = env and env.getscriptbytecode
			local decomp = env and env.decompile
			for i, scr in ipairs(scripts) do
				if not scanRunning then
					break
				end
				local path = getPath(scr)
				local bc, bcErr = nil, nil
				if getbc then
					local s, r = pcall(getbc, scr)
					if s and type(r) == "string" and #r > 0 then
						bc = r
					else
						bcErr = tostring(r)
					end
				end
				
				local src = nil
				if decomp then
					local s2, r2 = pcall(decomp, scr)
					if s2 and type(r2) == "string" then
						src = r2
					end
				end
				local blob = (bc or "") .. "\n" .. (src or "")
				local flags = {}
				if string.find(blob, "OnServerEvent") or string.find(blob, "OnServerInvoke") then
					table.insert(flags, "server handler")
				end
				if string.find(blob, "loadstring") then
					table.insert(flags, "loadstring")
				end
				if string.find(blob, "require%s*%(%s*%d+") then
					table.insert(flags, "require(assetId)")
				end
				if string.find(blob, "GetService%s*%(%s*[\"']ServerStorage") or string.find(blob, "ServerScriptService") then
					table.insert(flags, "server service ref")
				end
				if string.find(blob, "HttpService") and string.find(blob, "GetAsync") then
					table.insert(flags, "http get")
				end
				if bc and #bc > 32 then
					
					table.insert(flags, "bytecode:" .. tostring(#bc) .. "b")
				end
				if #flags > 0 then
					hits = hits + 1
					addFinding(3, "Bytecode", scr.ClassName .. ": " .. scr.Name, path,
						"Memory/bytecode pass flags: " .. table.concat(flags, ", "), scr, {bytecode = bc ~= nil})
				end
				if i % 5 == 0 then
					setStatus(string.format("Bytecode %d/%d", i, #scripts), 0.2 + 0.4 * (i / math.max(#scripts, 1)))
					task.wait()
				end
			end

			
			statusLbl.Text = "Scanning GC for script protos..."
			setStatus("GC memory sweep...", 0.65)
			local getgc = env and env.getgc
			if getgc then
				local seen = 0
				local s, objs = pcall(function()
					return getgc(true)
				end)
				if s and type(objs) == "table" then
					local getfenv = getfenv
					local getinfo = (debug and (debug.getinfo or debug.info)) or getinfo
					for _, o in pairs(objs) do
						if not scanRunning then
							break
						end
						if type(o) == "function" then
							seen = seen + 1
							local okEnv, envt = pcall(function()
								return getfenv and getfenv(o)
							end)
							local scrObj = okEnv and envt and rawget(envt, "script")
							if typeof(scrObj) == "Instance" and scrObj:IsA("LuaSourceContainer") and not isSkipped(scrObj) then
								local name = ""
								pcall(function()
									if getinfo then
										local info = getinfo(o)
										if type(info) == "table" then
											name = tostring(info.name or info.short_src or "")
										elseif type(info) == "string" then
											name = info
										end
									end
								end)
								if name ~= "" and (string.find(string.lower(name), "server") or string.find(string.lower(name), "backdoor") or string.find(string.lower(name), "admin")) then
									hits = hits + 1
									addFinding(4, "Bytecode", "GC proto: " .. name, getPath(scrObj),
										"Function in GC linked to script with server/backdoor-like name.", scrObj)
								end
							end
							if seen % 400 == 0 then
								task.wait()
							end
						end
					end
					log("GC functions scanned: " .. tostring(seen), Color3.fromRGB(200, 180, 120))
				else
					log("getgc unavailable or failed", Color3.fromRGB(255, 180, 100))
				end
			else
				log("getgc not present on this executor â€” skipped GC pass", Color3.fromRGB(255, 180, 100))
			end

			
			statusLbl.Text = "Checking nil instances..."
			setStatus("Nil instances...", 0.85)
			if env and env.getnilinstances then
				local s3, nils = pcall(env.getnilinstances)
				if s3 and type(nils) == "table" then
					for _, inst in ipairs(nils) do
						if typeof(inst) == "Instance" and inst:IsA("LuaSourceContainer") then
							hits = hits + 1
							addFinding(3, "Bytecode", "Nil script: " .. inst.Name, "nil::" .. inst.ClassName .. "." .. inst.Name,
								"Script exists with nil parent â€” often used to hide backdoor loaders.", inst)
						end
					end
				end
			end
		end)

		if not ok then
			log("Bytecode scan error: " .. tostring(err), Color3.fromRGB(255, 80, 80))
			if statusLbl then
				statusLbl.Text = "Error"
			end
		else
			if statusLbl then
				statusLbl.Text = hits > 0 and ("Done â€” " .. hits .. " traces") or "Done â€” no traces"
			end
		end
		renderResults()
		setStatus(string.format("Bytecode pass done â€” %d hits", hits), 1)
		log(string.format("Server bytecode / memory pass finished â€” %d hits", hits), Color3.fromRGB(120, 255, 120))
		task.wait(1.2)
		if overlay then
			overlay:Destroy()
		end
		scanRunning = false
	end

	local function startScan(opts)
		if scanRunning then
			log("Scan already running", Color3.fromRGB(255, 180, 80))
			return
		end
		scanRunning = true
		clearUI()
		setStatus("Starting scan...", 0.02)
		log("=== Backdoor / Remote Scanner ===", Color3.fromRGB(100, 200, 255))
		log("Scope: game content only (no CoreGui / engine)", Color3.fromRGB(160, 160, 160))
		local t0 = tick()
		task.wait()

		local ok, err = pcall(function()
			scanRemotes()
			if opts and opts.autoProbe ~= false then
				autoProbeBackdoors()
			end
			scanScripts(opts and opts.decompile ~= false)
			scanAssetsAndGear()
			scanCrashAndLagSurfaces()
			scanServices()
			if opts and opts.ai then
				runAIAnalysis()
			end
		end)
		if not ok then
			log("Scan error: " .. tostring(err), Color3.fromRGB(255, 80, 80))
			setStatus("Error: " .. tostring(err), 1)
		end

		renderResults()
		local elapsed = math.floor((tick() - t0) * 10) / 10
		setStatus(string.format("Done â€” %d findings in %.1fs", #findings, elapsed), 1)
		log(string.format("Finished in %.1fs | %d findings", elapsed, #findings), Color3.fromRGB(120, 255, 120))
		scanRunning = false
	end

	GameScanner.Init = function()
		window = Lib.Window.new()
		window:SetTitle("Game Scanner")
		window:Resize(640, 500)
