		toolbar.Parent = contentFrame

		local function makeBtn(text, x, w, cb)
			local b = Instance.new("TextButton")
			b.Size = UDim2.new(0, w, 0, 22)
			b.Position = UDim2.new(0, x, 0, 3)
			b.BackgroundColor3 = Color3.fromRGB(55, 55, 55)
			b.BorderSizePixel = 0
			b.Text = text
			b.TextColor3 = Color3.new(1, 1, 1)
			b.Font = Enum.Font.SourceSans
			b.TextSize = 13
			b.Parent = toolbar
			b.MouseButton1Click:Connect(cb)
			return b
		end

		makeBtn("Quick Scan", 6, 80, function()
			task.spawn(function()
				startScan({decompile = false, ai = false})
			end)
		end)
		makeBtn("Full Scan", 90, 80, function()
			task.spawn(function()
				startScan({decompile = true, ai = false})
			end)
		end)
		makeBtn("Full + AI", 174, 90, function()
