		makeBtn("Clear", 268, 60, function()
			if not scanRunning then
				clearUI()
				setStatus("Cleared", 0)
			end
		end)
		makeBtn("Stop", 332, 50, function()
			scanRunning = false
			log("Stop requested", Color3.fromRGB(255, 180, 80))
		end)
		makeBtn("Bytecode", 386, 70, function()
