["DataStoreEditor"] = function()
local Main,Lib,Apps,Settings
local Properties
local API,RMD,env,service,plr,create,createSimple

local function initDeps(data)
	Main = data.Main
	Lib = data.Lib
	Apps = data.Apps
	Settings = data.Settings
	API = data.API
	RMD = data.RMD
	env = data.env
	service = data.service
	plr = data.plr
	create = data.create
	createSimple = data.createSimple
end

local function initAfterMain()
	Properties = Apps.Properties
end

local function main()
	local DataStoreEditor = {}
	local window
	local listFrame, statusLabel
	local selectedPlayer

	local playersService = service.Players

	local function showEditor(player)
		if not player then return end
		Properties.DisplayValueEditor(player)
	end

	local function refreshList()
		if not window or not listFrame then return end
		for _, child in ipairs(listFrame:GetChildren()) do
			if child:IsA("TextButton") then child:Destroy() end
		end
		local rowY = 2
		for _, player in ipairs(playersService:GetPlayers()) do
			local row = Instance.new("TextButton")
			row.BackgroundColor3 = Settings.Theme.Button
			row.BorderSizePixel = 0
			row.Position = UDim2.new(0, 0, 0, rowY)
			row.Size = UDim2.new(1, 0, 0, 22)
			row.Font = Enum.Font.SourceSans
			row.TextSize = 14
			row.TextXAlignment = Enum.TextXAlignment.Left
			row.Text = player.Name
			row.TextColor3 = Settings.Theme.Text
			row.Parent = listFrame
			row.MouseButton1Click:Connect(function()
				selectedPlayer = player
				if statusLabel then statusLabel.Text = "Selected " .. player.Name end
				showEditor(player)
			end)
			rowY = rowY + 24
		end
	end

	window = Lib.Window.new()
	window:SetTitle("DataStore Editor")
	window:Resize(320, 460)

	local titleLabel = Lib.Label.new()
	titleLabel.Text = "Players - click one to edit its data"
	titleLabel.Position = UDim2.new(0, 12, 0, 8)
	titleLabel.Size = UDim2.new(1, -24, 0, 18)
	window:Add(titleLabel)

	listFrame = Instance.new("ScrollingFrame")
	listFrame.BackgroundColor3 = Settings.Theme.Main2
	listFrame.BorderColor3 = Settings.Theme.Outline1
	listFrame.BorderSizePixel = 0
	listFrame.ScrollBarThickness = 6
	listFrame.Position = UDim2.new(0, 12, 0, 30)
	listFrame.Size = UDim2.new(1, -24, 1, -70)
	listFrame.Parent = window.ContentPane

	statusLabel = Lib.Label.new()
	statusLabel.Text = "Select a player to edit their data"
	statusLabel.Position = UDim2.new(0, 12, 1, -24)
	statusLabel.Size = UDim2.new(1, -24, 0, 18)
	statusLabel.TextColor3 = Settings.Theme.ReadOnlyText
	statusLabel.TextTruncate = Enum.TextTruncate.AtEnd
	window:Add(statusLabel, "Status")

	refreshList()

	playersService.PlayerAdded:Connect(function() refreshList() end)
	playersService.PlayerRemoving:Connect(function() refreshList() end)

	DataStoreEditor.Window = window
	DataStoreEditor.Refresh = refreshList
	DataStoreEditor.showEditor = showEditor
	DataStoreEditor.Init = function() end

	return DataStoreEditor
end

return {InitDeps = initDeps, InitAfterMain = initAfterMain, Main = main}
end,
}

